quests[49956] = { id = 49956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void is Prohibited", description = "Scans indicate errors in reality surrounding nearby structure. Portals directly to the Void.\n\nCurrent theory, corruption has Old God as source. Void attracted to Old God corruption.\n\nPortals must be sealed to contain entities lured here by Old God corruption.\n\nTake this device. Titan Keeper Hezrel has forged it thanks to help in powering up systems.\n\nUse device to seal Void portals, prevent more void entities from entering area.", completion = "Void portals no longer detected. Must continue.", objectives = "Seal 4 Void Portals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49957] = { id = 49957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protocol Recovery", description = "System repairs progressing. One key component needed: containment protocol. \n\ncontainment protocol will fully reboot defensive systems. Allow Titan Keeper Hezrel to properly maintain containment.\n\nScans indicate large creature within temple has absorbed slab containing containment protocol. Creature exists between this plane and Void.\n\nRequest: destruction of creature and retrieval of protocol.", progress = "Please present containment protocol.", completion = "Containment protocol obtained. System reboot initiated.", objectives = "Retrieve Containment Protocol from Overlord Kraxis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49960] = { id = 49960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sic 'Em!", description = "Humphrey's a good tracker, to be sure. He's also the orneriest, angriest, most dogged dog if he sets his eyes on a quilboar. This will certainly be useful.\n\nBelow our very noses, the foreman organizes and directs the tunnelers to cause the most mayhem and destruction. If you can put an end to him, it should make things a lot easier for us to move around the farmlands.\n\nHumphrey looks a bit hungry, wouldn't you say? Why don't you bring him with you to take care of business?", progress = "If I could rate Humphrey, I'd give him at least a twelve out of ten.", completion = "Jolly good. With him out of the way, the quilboar around here should be less organized and take longer to mobilize.", objectives = "Defeat Foreman Razorgnarl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49965] = { id = 49965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warpack", description = "Zul began a coup, but he did not secure de pyramid for himself. Nor has he done anything to rally more to his banner outside of those who were already conspiring with him.\n\nDis concerns me more than if he had carved his face into Dazar'alor itself.\n\nWe must learn what he is up to. Join de disciples of Gonk and ride ahead to de Temple of the Prophet. Look to Wardruid Loti for further orders when you arrive.", progress = "Good hunting.", completion = "Blood calls out for blood.", objectives = "Ride with Gonk to the Temple of the Prophet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49969] = { id = 49969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awaken a God", description = "You see the sinking ruins to the east? They were, not long ago, a temple to the shark loa, Gral.\n\nThe naga tore down his temple and are stealing his secrets. If it is for something good, I'll be a rock's uncle.\n\nIt would be wise to let Gral know what's going on here. I do not think he would approve.\n\nGral was quite powerful, and when it came to his knowledge of the sea, none could compare. It never hurts to have a fellow like that on your side.\n\nSome fresh, bloody naga meat may just lure him out.", progress = "<There is a feeling of anticipation emanating from the bowl.>", completion = "Now this! This is an offering worthy of my attention!", objectives = "Gather chunks of naga flesh as an offering to Gral.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49973] = { id = 49973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalyssra's Estate", description = "Would you like to hear how the nightborne came to join the Horde?\n\nWe earned their trust when we aided them in liberating Suramar from the tyranny of Grand Magistrix Elisande and the Burning Legion.\n\nLor'themar Theron later asked them to join him in Quel'Thalas. Lady Liadrin made the journey to extend the invitation to First Arcanist Thalyssra...", completion = "The city of Suramar is beautiful to behold. I hope Silvermoon City is not a disappointment to them.", objectives = "Meet with Lady Liadrin at the Estate of the First Arcanist in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49975] = { id = 49975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest in the Depths", description = "This passage flows through the Shrine of the Storm out into the open sea. We will release the souls of the fallen here.\n\nLegends say that as our spirits pass through the Shrine, they aid in the great blessing rituals that all Kul Tiran ships undergo. \n\nIn that way, we Stormsong never stop serving our people.", progress = "The sea demands respect. To cross it is to invite its wrath upon us all.", completion = "Thank you for aiding me in my solemn task.", objectives = "Complete the Ritual of Release.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49976] = { id = 49976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gifts of the Fallen", description = "Earlier today, King Wrynn addressed the citizens of Stormwind at Lion's Rest in a speech given to formally announce the end of the war.\n\nAfter the crowd departed, I met privately with the King and his advisors to discuss a mysterious substance that has been found in Silithus.\n\nThis glowing ore appears to be most powerful and the Horde has wasted no time in extracting it from the great wound.\n\nThe king has ordered me to fill you in on the details, in preparation for an important mission.", completion = "If this strange substance is as powerful as it appears to be, we cannot allow it to fall into the wrong hands. Your presence will be needed in Silithus.", objectives = "Speak with Mathias Shaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49977] = { id = 49977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons to Orgrimmar", description = "The Warchief has requested that you return to Orgrimmar as soon as possible. There is an urgent matter that requires your attention.\n\nI will fill you in on the details as soon as you arrive.\n\nYou will find me near the entrance of Grommash Hold. The Dark Lady has plans for you, {name}. I would not keep her waiting...", completion = "About time you arrived, {name}. The very future of the Horde may depend on what I am about to tell you...", objectives = "Speak with Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49980] = { id = 49980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containment Procedure", description = "Scans indicate structure has become inoperable. No possibility for repair.\n\nTitan Keeper Hezrel's database fully restored. Believe solution may be within data.\n\nRequire time to scan data, find solution to contain Old God corruption.\n\nStand by while Titan Keeper Hezrel scans databanks for solution.", progress = "Please stand by.", completion = "New protocol initiated. Defeat of blood trolls critical priority.", objectives = "Observe Titan Keeper Hezrel scan for a solution to Nazmir's old god corruption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49981] = { id = 49981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witness to the Wound", description = "I've already sent operatives to Silithus to establish a base camp.\n\nTheir orders are to monitor the operations of the Horde and gather any information they can find on this mysterious substance.\n\nOne of my SI:7 commanders is currently awaiting your arrival. Go with speed.", completion = "Well met, {name}. It's good to have someone of your renown here with us in Silithus.", objectives = "Meet with the SI:7 commander in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49982] = { id = 49982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witness to the Wound", description = "The Bilgewater Cartel have already begun mining operations in Silithus to extract this mysterious substance.\n\nThe Warchief has insisted that you personally oversee the extraction efforts in Silithus and prevent the Alliance from interfering.\n\nGallywix seemed less than pleased with your appointment, but nobody refuses Sylvanas...\n\nYou must go to Silithus at once. The base commander is awaiting your arrival.", completion = "Greetings, {name}. I was told you'd be coming. The mining operation is currently underway.", objectives = "Speak with Grol Warblade in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49985] = { id = 49985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Gloom Hollow", description = "Old God G'huun behind destruction of this seal. Commanding blood trolls to destroy final one within Zuldazar.\n\nTitan Keeper Hezrel must aid in destruction of blood trolls. Cannot allow Zuldazar seal to be destroyed and G'huun to be freed.\n\nMust leave interior of Atul'nazman. Meet Titan Keeper Hezrel outside of temple, will help return to Gloom Hollow.\n\nWhen task is complete, Titan Keeper Herzrel must establish contact with other keeper within G'huun containment chamber.", completion = "We have everything we need to go after de blood trolls. We need to get moving.", objectives = "Meet Titan Keeper Hezrel outside of Atul'nazman to return to Gloom Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49991] = { id = 49991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Featherfeet's Fun Falling's Fun Fee!", objectives = "Pay 100 gold to Quinsy Featherfeet and he'll cast Slow Fall on you whenever you're nearby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49994] = { id = 49994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sliding with Style" }
quests[49995] = { id = 49995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabricated Fabrications", description = "There was somethin' off with the ship we were building in the yard. I never saw the blueprints, but I've built enough ships in my day to know it wasn't business as usual.\n\nThey've kept all the pages under tight guard in the Brineworks up the road lately. Full on militia.\n\nIf you can get your hands on enough of them pages, we oughta be able to figure out what Lord Stormsong and his boys are schemin'.", progress = "Any luck recovering those blueprints?", completion = "I knew they'd still have 'em! If you ever want something gone, lad you'd best destroy it yourself.", objectives = "Recover 8 Warship Blueprints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49996] = { id = 49996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rearmament", description = "The people of this valley have true hearts, {name}. They're eager to take back control of their home.\n\nWe have to help them.\n\nThe Brineworks up the road from here supplies most of House Stormsong's weapons. Our movement here could make great use of them.\n\nIf you can collect enough to go around, I'll go over some basic training with our friends here.", progress = "There are still many who don't follow Lord Stormsong. We need to stand by them.", completion = "This valley belongs to its people. We must fight to make it whole again!", objectives = "Collect 12 Stormfused Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49997] = { id = 49997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm's Judgment", description = "When I opened my mind to the currents during the ritual, I felt the presence of a member of Lord Stormsong's innermost circle.\n\nWavespeaker Reid. If anyone can locate the missing fleet, it is him.\n\nI will not stand by while my brothers move against our own people. Oaths be damned.\n\nWe must force Reid to see reason.", progress = "This must be done.", completion = "I never thought Reid would succumb to darkness. Things are worse than I feared.", objectives = "Confront Wavespeaker Reid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49998] = { id = 49998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voices Below", description = "The others forged ahead to Port Fogtide. I doubt they will receive a warm welcome. \n\nWe are to meet them there. However, there is something I must do first.\n\nDespite Reid's retreat I still feel a terrible darkness nearby; I wish to listen to the tides for answers. I would appreciate your joining me in case more danger strays into our path.", completion = "We must help the others before they are overrun!", objectives = "Help Brother Pike investigate his omen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50000] = { id = 50000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastly Dealings" }
quests[50001] = { id = 50001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Hag", description = "The town is overrun! \n\nThe guards have fallen back and what is worse, some of the villagers have been twisted by the witches' magic. They are little more than wretched beasts blindly following orders. \n\nWe must release these poor souls and slay the monsters that twisted them!\n\nSee what you can do to cut down the numbers of monsters in town!", progress = "We have a little breathing room.", completion = "Well done. You've thinned their numbers.", objectives = "Kill 15 Briarwood Creatures and Witches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50002] = { id = 50002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Very Precious Cargo", description = "We weren't the only ship in our convoy to get caught up in this mess. Our flagship ran aground to the east. It was holding a very precious cargo and I need you to bring it back here.", completion = "Who are you? Where's my dad? I'm hungry. Can I have a sword? Where's my dad?!", objectives = "Find the \"Precious\" cargo in Fogcliff Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50003] = { id = 50003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Watch", description = "As you can see, the coven has conscripted my own guardsmen into their service. Though I am loath to battle my own, these men are too corrupted by the coven's magic to be saved.\n\nFor them, death is the only mercy we can give.\n\nThe Inquisitors and I can handle the regiment stationed outside. We will need you to find and take out their leader.\n\nYour Inquisitors await your command, {class}. Are you ready to take the tower?", progress = "We assault the tower at your command.", completion = "Well fought, {class}.  The tower is ours.\n\nNow, we should set our sights on Corlain proper!", objectives = "Defeat Sister Adela at Watchman's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50005] = { id = 50005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hold My Hand", description = "Take me to my daddy this instant!\n\nWaaaait! You have to hold my hand...", progress = "Where is she? Don't tell me you lost her.", completion = "You found my precious little sea star!", objectives = "Escort Penny back to her father.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50009] = { id = 50009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipwreck Recovery Crew", description = "Fogcliff Strand is swarming with Sirens and Saurolisks! Clear them out and grab any remaining cargo from the ships." }
quests[50026] = { id = 50026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Our Shipmates", description = "Oh, thank the stars! Our ship ran aground and our men are in desperate need of help.\n\nFind Henry Hardwick down the hill at the shipwreck. He stayed behind to try and help the others.", completion = "We need your help, sailor!", objectives = "Find Henry Hardwick in Fogcliff Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50035] = { id = 50035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bret Test - SQL" }
quests[50036] = { id = 50036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Weapon of Old", description = "I've been studying the parchment Lady Lucille sent with you and have translated some of the older language. \n\nThey called it \"Liquid Fire\" and it was used to \"burn away the Drust\". Using this as a basis I believe we can adapt it to our needs. This is a complex recipe, but it just so happens I have everything we need to make this potent alchemical weapon!\n\nI will need your assistance in creating this. Would you be so kind as to help?", progress = "We'd better get cooking!", completion = "Wonderful! Smells a bit strong but I think it will burn those wooden constructs well! Now it's time to test it out.", objectives = "Help Master Ashton create the Liquid Fire potion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50041] = { id = 50041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pocketful of Shells", description = "You see the problem? No you don't.\n\nProblem isn't all these dang quilboar. Quilboar I can shoot all day. Been shootin' em all my life, since my pappy gave me my first gun. \n\nProblem is these pigs are tough. Tougher'n they've been before. Can't kill em like I used to, see? My new modified bullets just get stuck in them and they refuse to die!\n\nHere, take my knife. Go out there and kill some of the quilboar and get my ammo back. Then I can shoot the rest! I won't stop 'till there's none left to shoot!", progress = "Pretty sure I'll have to start shootin' my dinnerware, and I only have three sets. Hurry up, will you?", completion = "Good! I can keep shooting, and they can't get to me! This is really the perfect setup.", objectives = "Collect 20 Salvaged Azerite Ammunition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50043] = { id = 50043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaeological Efficiency", description = "Miss Tae'shara and I share a passion for uncovering hidden secrets and a deep, abiding respect for this ancient land.\n\nThat said! If we were to continue at the pace to which she is accustomed, the Alliance would overtake us before we could make a single discovery. \n\nIt is time to expedite our survey.\n\nThe ruins hide many fossils. Take a beacon and use it to summon one of my sweepers. It will clear away the topsoil and allow you to collect samples.\n\nGather what you can- we can assemble them later.", progress = "I simply see no reason to dirty our hands, {name}.", completion = "Hm. These are a little... broken, don't you think?\n\nAh, well, nothing a little magic cannot fix.", objectives = "Collect 50 Xibalan fossil fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50044] = { id = 50044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaeological Efficiency", description = "Suppose I owe the lass her bones if I'm tae be monopolizin' yer time. And I will be.\n\nGo on out into the ruins an' use this here stone to call one of my rumbly elemental friends. They'll blast away any dirt 'tween you an' the fossils.\n\nWe could go about this the ol' fashion way, but do you really want to spend all day digging? Course ye don't.\n\nAcadia will see that a little efficiency gets everyone what they want.", progress = "<Acadia eyes Morgrum sourly.>\n\nI don't think he cares one lick about our expedition, {name}.", completion = "<Acadia stares at the fragments, dismayed.>\n\nI'll just... clean these up... See what we can salvage.\n\nThanks?", objectives = "Use the Elemental Summoning Stone to expose Xibalan fossils. Bring 50 Xibalan Fossil Fragments to Acadia Chistlestone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50046] = { id = 50046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Sabotage", description = "The Horde has wasted no time in shamelessly extracting this mysterious ore from the great wound.\n\nLuckily for us, goblin engineering is not nearly as sophisticated as what we create in Gnomeregan! All it takes is a little bit of old fashioned dynamite to completely disable a goblin shredder.\n\nWhat unsophisticated machinery!\n\nTake these dynamite bundles and plant them on the inactive shredders around the mining camp.\n\nIt'll take those greedy goblins weeks to get back up and running again!", completion = "Great work, {name}! With the shredders sabotaged, the Bilgewater Cartel mining operation will grind to a halt!", objectives = "Plant 10 dynamite bundles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50047] = { id = 50047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Samples", description = "The crown has ordered SI:7 to infiltrate the goblin mining operation and collect any information we can find on this mysterious new substance.\n\nMy agents have infiltrated the camp, but the clock is ticking and we need to get our hands on some extracted ore samples fast.\n\nIn other words, I need someone who can take the direct approach. Someone who can handle a fight against overwhelming odds and come out alive.\n\nTake the ore samples to Khargus Stonemantle for analysis when you return.", progress = "What have ye got for me?", completion = "I've never seen anythin' like this before... I'll get to work examinin' it at once!", objectives = "Collect 8 Mysterious Ore samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50048] = { id = 50048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seething Shore", description = "We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits.\n\nIt is vital that we secure the island before the Horde learns of its existence.\n\nMaster Mathias Shaw is personally leading the expedition force and has requested that you report for duty. Good luck!", completion = "You made it back alive. That's good news, indeed! I trust the expedition went well?", objectives = "Complete the Seething Shore battleground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50049] = { id = 50049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker's Perspective", description = "Sargeras has left a scar upon our world, {name}. A scar that will not soon heal...\n\nIt appears that the scars between the Alliance and Horde have yet to heal as well.\n\nToo many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more.\n\nI have a request for you before I go. Take this letter to Magni Bronzebeard. He is in Silithus seeking a way to heal the wound.\n\nThe letter contains information that may prove valuable to him.", completion = "Thank you for delivering Khadgar's letter ta me. I'm goin' ta need some time ta consider his words. If what he says is correct, we may be able ta save Azeroth... but at a great cost.", objectives = "Deliver Khadgar's letter to Magni Bronzebeard in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50052] = { id = 50052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Spies Allowed", description = "Hey {name}, I'm glad you're here.\n\nI'm in way over my head! Killer bugs, a strange substance... that GIANT sword sticking outta the ground... I don't have a good feelin' about this place!\n\nTo make matters worse, I've been gettin' reports of Alliance spies snoopin' around the camp!\n\nLook kid, the Dark Lady has plans for this mysterious ore and I ain't going to be the one to dissapoint her, know what I mean?\n\nGet over to the mining camp and take out those SI:7 spies before they ruin the whole operation!", completion = "You did well, {name}... Crisis averted! But we better keep an eye out for reinforcements.\n\nIf this stuff is as valuable as Gallywix says it is, the Alliance is going to be all over this place in no time!", objectives = "Kill 10 SI:7 Operatives in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50053] = { id = 50053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lazy Prospectors!", description = "I've been around long enough to know you can never trust a goblin with an orc's work.\n\nGallywix and his cartel may be serving the warchief, but we need to keep a close eye on them if we're going to get anything done!\n\nI've already noticed many of the workers loafing about and sleeping on the job. The Horde does not tolerate laziness!\n\nGet out there and put those lazy prospectors in their place!", completion = "Hmmpf! I hope you didn't go easy on them. If it were up to me they'd be getting more than a simple beating!", objectives = "Motivate 10 Lazy Prospectors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50054] = { id = 50054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seething Shore", description = "We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits.\n\nIt is vital that we secure the island before the Alliance learns of its existence.\n\nNathanos Blightcaller is personally leading the expedition force and has requested that you report for duty. Go with honor!", completion = "I'm pleased to see that you made it back alive. I'm sure you fought with honor!", objectives = "Complete the Seething Shore battleground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50055] = { id = 50055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker's Perspective", description = "Sargeras has left a scar upon our world, {name}. A scar that will not soon heal...\n\nIt appears that the scars between the Alliance and Horde have yet to heal as well.\n\nToo many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more.\n\nI have a request for you before I go. Take this letter to Magni Bronzebeard. He is in Silithus seeking a way to heal the wound.\n\nThe letter contains information that may prove valuable to him.", progress = "What do ye have for me, {class}?", completion = "Thank you for delivering Khadgar's letter ta me. I'm goin' ta need some time ta consider his words. If what he says is correct, we may be able ta save Azeroth... but at a great cost.", objectives = "Deliver Khadgar's letter to Magni Bronzebeard in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50056] = { id = 50056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker's Call", objectives = "Meet Magni Bronzebeard at the Wound in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50057] = { id = 50057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power in Our Hands", objectives = "Go to the Sword in Silithus and draw its power into your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50058] = { id = 50058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witch's Pet", description = "I've seen her! The witch!\n\nEvery once in a while she comes down to the cave, checking on her pet. I've never seen a spider so large!\n\nShe spreads her spell, cursing all of the animals in these woods to follow her command and attack us.\n\nThe broodmother laid all these eggs, and they're hatching into more possessed beasts!\n\nTake her out, and perhaps the infestation will stop.", completion = "<With the spider matriarch defeated, the flow of cursed spiders should slow, if not stop completely.>", objectives = "Kill the Mossfang Matriarch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50059] = { id = 50059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Hear A Thing", description = "These snake wenches show up and everyone loses their minds! All my men are head over heels for these things. Personally, I don't see it. I mean, I sort of get the appeal, but the wings for arms and snake tails are a big turn off.\n\nThere's a big one in a cave to the east. She's got a whole heap of suitors. I need them back to work. Go give her a wallop and get everyone back here.", completion = "I decided if you can't beat 'em, join 'em! That one over there looks available. Think she'll go out with me?\n\nOh, and thanks for getting everyone back at their posts. We got a lot of cleanup.", objectives = "Kill Anthemusa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50063] = { id = 50063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting With Fire", description = "Excellent! Now that we have these lovely Liquid Fire flasks prepared we have one last thing to do:\n\nTest them out!\n\nThere are some of those large abominations lurking about in the woods above my home. I think they would make excellent test subjects for our little alchemical experiment, wouldn't you say?", progress = "Help!", completion = "I tried to stop them but I couldn't. They've taken Master Ashton into the woods!", objectives = "Test the Liquid Fire flasks on 3 Briarwood Bulwarks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50064] = { id = 50064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Go in the Basement", description = "We checked everywhere... well, <gulps> everywhere except the basement.\n\nB-b-but, dad told me never to go down there.\n\nHe said it's dark, scary, and dangerous to go alone... I could be eaten by a brue!\n\nI don't even know what that is, but I don't wanna be eaten! \n\n{name}, do you think you could go down first?", completion = "The brue, I saw it. He didn't make it up!!", objectives = "Enter the basement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50065] = { id = 50065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Reason to Stay", description = "<You find a pocketwatch on the ground. It is dirty, but still works. It was taken care of well.\n\nPerhaps there are other objects that Goldfield wasn't able to grab before he had to hole up in his house. He might appreciate it if you brought them to him.>", progress = "For the last time, I'm not leaving! I was here first, THEY can leave!", completion = "You... you found them. I...", objectives = "Search the Goldfield Farmstead for additional keepsakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50069] = { id = 50069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldfield's War", description = "I'm not leaving. I'm never leaving.\n\nThose quilboar, they killed them. I gave her the watch, told her to hurry. Grab our boy and get to the house while I got the gun...\n\n<Goldfield is choking back tears.>\n\nI won't leave. Our family has our roots here. They would want me to stay, don't you understand? This is our farm. My boy, he wanted to join the militia. I made him a sword...\n\n<Goldfield takes a deep breath.>\n\nNow you know. Help me retake my farm. Grab a gun and let's kill every last one.", progress = "This is MY home!", completion = "It's done. My family is avenged.", objectives = "Defeat the quilboar invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50070] = { id = 50070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detective Mildenhall", description = "Hmm... okay, okay, let's think.\n\nIf you were my dad and you accidentally set loose a bunch of honey monsters all over the place, what would you do?\n\nWell, okay, you would probably beat all of them up. But he probably ran away.\n\nIf he left in a hurry, maybe he left something for us to find.", progress = "Did you find anything else?", completion = "Hmm... we checked everywhere.", objectives = "Search the Mildenhall Meadery for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50071] = { id = 50071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Light!", description = "The Lightforged Draenei will be happy to join the Alliance.\n\nOur cause is now yours, {name}.\n\nLet us return to Stormwind. Captain Fareeya will speak with our people.", completion = "The stories of the Lightforged echo throughout the streets of Stormwind. An army of elite soldiers dedicated to fighting the Legion... they will be one of our strongest allies.", objectives = "Return to Stormwind and speak with Aysa Cloudsinger to hear the end of his tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50074] = { id = 50074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutal Boost", description = "The Aggression Formula is ready and I need you to inject Ben'jin with it. \n\nLet's show the world, and the witch doctor, that well researched, dramatically overpowered, double-blind, peer-reviewed, super goblin science is the right way to do, uh, pretty much anything!", progress = "This is exciting, isn't it?", completion = "I spent several moments working out that formula! It should have worked! The reason these brutosaurs are endangered is clearly their unreasonable resistance to science!", objectives = "Administer the Aggression Formula to Gentle Ben'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50076] = { id = 50076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally the Warriors", description = "We have learned so much and came so far thanks to you and de Horde, but all of it will amount to nothing if de blood trolls defeat us here.  \n\nWe've all worked hard since we first set foot within dis accursed swamp, without a chance to even get any sleep or have a decent meal. Dey are some of de finest soldiers I've ever encountered, but even dey have their limits.  \n\nLet us remind dem what we are fighting for!", progress = "We must carry on. De fate of my home is in our hands.", completion = "We are ready. Now, it is time for us to bring our fight to de blood trolls!", objectives = "Ring the Ancient Gong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50078] = { id = 50078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undying Totems", description = "De blood trolls are putting up quite de fight. Dey are raising de very dead to go against us!\n\nTheir necromancers are raising de dead with de help of totems fueled with blood magic. Destroying dem should take de pressure off our troops.", progress = "Why are you talking to me when those totems are still out dere?", completion = "Good work, dat should make things easier on us.", objectives = "Destroy 3 Reanimating Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50079] = { id = 50079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom goes the Bomb", description = "Just look at 'em... those blood trolls are holed up pretty good down there in that fortress of theirs. Multiple defensive lines, lots of equipment, they got everything.\n\nThey're completely unprepared for us! I almost feel sorry for 'em!\n\nLet's start off by showing 'em what we think of their cute attempts at making barricades. Here, take these smoke grenades and put a signal right on top of them. We'll see how well they hold up to high explosives!", completion = "Good job! Now we can move deeper into dis den of evil.", objectives = "Call artillery strikes on the Blood Troll Barricades in Zul'Nazman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50080] = { id = 50080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raiding the Raiders" }
quests[50081] = { id = 50081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road of Pain", description = "My people continue to be captured and hauled into de blood trolls' village for de slaughter, to be used as fuel for their dark rituals. \n\nJust ahead, I can see some of de captives who fell along de path. I hear their cries as de blood trolls perform their vile rituals upon dem.\n\nWe cannot leave my people to die in de swamp, {name}!\n\nTake dese bandages and save any Zandalari you encounter down dere.", progress = "Were you able to help de others?", completion = "Our soldiers will return home stronger, wiser, and most importantly, alive.\n \nOn behalf of my people, I thank you.", objectives = "Save 6 injured Zandalari Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50082] = { id = 50082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target of Opportunity", description = "It seems our actions here have not gone unnoticed, {name}. I feel a dark presence ahead.\n\nAteena is near! \n\nDis is our chance! If we strike now, we can deal a huge blow to de blood trolls!\n\nWe must move!", completion = "She is... so much stronger than I expected. But, we have some surprises of our own! \n\nLet us bring up dis gun of yours and see how well it performs.", objectives = "Confront Grand Ma'da Ateena.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50083] = { id = 50083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crawg Ma'da", description = "No matter what we do, as long as dem blood trolls have their village here, dey gonna be a threat.\n\nWe gonna put an end to dat threat!\n\nAmaka be da strongest blood troll I ever seen, and she be right across da way there. She be feedin' da bodies of da Zandalari ta her pet crawgs, makin' dem big, fat, and deadly. It be time for revenge, and we be doin' it wit' da help of her own pets.\n\nGo kill a crawg and cut its poison gland out of its belly. With it, ya can weaken Amaka and put an end to her.", completion = "Well done, {name}! \n\nDa blood trolls gonna be hurtin' wit' da death of their general. Now, let's keep da pressure on dem!", objectives = "Obtain a Crawg Poison Gland and slay Amaka the Crawg Ma'da.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50084] = { id = 50084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back On Your Feet, Soldier", description = "I figured any soldiers we be coming across might be wantin' some revenge, so I brought along some extra weapons just in case.\n\nSee up ahead? Dem cages be full of trolls awaitin' der turn ta die. We gonna swoop in der and be da answers to der prayers!\n\nGo and arm as many of dem as ya can, revenge gonna be sweet!", objectives = "Give weapons to 10 Zandalari Captives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50085] = { id = 50085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message of Blood and Fire", description = "Look at what I be findin' here. Dis one had a magic wand in his hand.\n\n<Rokhan shuts his eyes for a moment.>\n\nMmmmm... it be warm. Mojo of fire be within. Perfect!\n\nTake dis ting an' give 'em a taste of their own firepower.\n\nBurn da whole village down!", completion = "Good job, mon. Justice be served.", objectives = "Use the Wand of Embers to set ablaze 8  Blood Troll huts in Agwamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50087] = { id = 50087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ateena's Fall", description = "You have proven to be a much greater ally dan I could have ever hoped. Thanks to you and your Horde, we have come dis far. Now, there is only one thing dat remains. \n\nWe must confront de leader of de blood trolls and put an end to their dark plot once and for all.\n\nWithout Ateena's mojo to protect it, we can finally destroy dat monstrosity of theirs before it can be unleashed upon Zuldazar. \n\nYou know what must be done. \n\nFirst, I must prepare myself. Go. I will join you when de battle has begun.", completion = "Finally, our battle here is done!\n\nMore importantly, you have made good friends with de tortollans and have gained powerful allies in de loa. I feel dat we will need to call upon their aid in de future.\n\nIt is time for me to return to Zuldazar and let my father know of our victory. \n\nDo you hear dat? Rokhan appears to have a message for us.", objectives = "Slay Grand Ma'da Ateena.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50088] = { id = 50088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golden Fields Forever", description = "I can take care of the rest. That ettin would have given me trouble if I was by myself, so you have my thanks.\n\nI would ask you for one more favor.\n\nMy wife, she loved the carnations that grow by the water's edge. If you could gather some, there's a nice spot under a tree by the river. We loved to go there when the sun set after our days in the fields.\n\nOur boy would run around, catching bugs, making reed whistles...", progress = "That's that, then.", completion = "Thank you, {class}. They will rest now.", objectives = "Lay Farmer Goldfield's family to rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50090] = { id = 50090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building Defenses", description = "We'll be able to push those monsters back now, but my defenders won't stand a chance unless we build a forward barricade for protection.\n\nThere should be plenty of lumber to build a barricade near the entrance to town.", progress = "We've pushed the front line out. That will give us some room.", completion = "Thank you. We'll be better able to protect the town.", objectives = "Collect lumber to build forward barricades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50091] = { id = 50091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Village Repair" }
quests[50092] = { id = 50092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curiously Strong", description = "I imagine the fires spread while I was down here, yes? First order of business then; making sure the town doesn't burn down! Help solve that problem and I shall be free to assist you in... whatever it is?\n\nLet's see... Yes! Here! Take these. They proved to be bit too... intense for most people, but you seem like a stout sort.\n\nJust be sure you're facing the fires when you use them, and I'm certain those fires will be out in no time!", progress = "If we don't stop the fires, they could spread!", completion = "Ah wonderful! The fires are out and your breath smells minty fresh!", objectives = "Use the Frost Breath Potion to put out the fires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50110] = { id = 50110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bearers of Bad News", description = "We must report this attack to Lord Admiral Katherine Proudmoore and prove to her that Lady Ashvane is behind it.\n\nIt won't be easy... Lady Ashvane and Katherine Proudmoore have been close friends for years.\n\nQuickly, let us make for Boralus!", completion = "It seems word of the attack has already reached Boralus.", objectives = "Return to Boralus with Taelia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50111] = { id = 50111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totems, Totems, Totems!", description = "<This totem pulses with energy, releasing it into the nearby idols and thorns.\n\nIt looks rather fragile... It would be a shame if something happened to it.>", completion = "Good idea! Smashing those will distract their mystics and set back their expansion.", objectives = "Destroy the Brambleguard Totems in Briarback Kraul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50112] = { id = 50112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Casting the First Stone", description = "Hey dere {name}, gimme a hand with dis, would ya?\n\n<Kumali motions you over to her.>\n\nI got dis recipe dat I've been trying to remember de rest of, but I'm having de hardest time coming up with de right ingredients.\n\nYa see, my partner ran off with de other half of de recipe on account of a disagreement we had. But dis stone, it's a treasure like no other.\n\nGrab some vials and start mixing dese ingredients together. Let's see if dey are de right ones.", progress = "I will never ask for de other half of de recipe back from dat... dat... imbecile. I'll figure it out, ya see.", completion = "Okay, {name}, let's see if dis works.", objectives = "Craft a Potion of Durability and a Potion of Shifting States using the recipes given to you. You can find the ingredients you need in Kumali's shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50113] = { id = 50113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ocular Extracts", description = "So dere's a creature in dese lands whose eyes are perfect for alchemical recipes.\n\nDey might just be de thing we need to finish dis project. Although, I don't remember seeing dem on de full recipe list de last time I saw it, ya see... But my memory isn't quite what it used to be.\n\nGah! I'm rambling too much. Get me some eyes, will ya, {name}?", progress = "Make sure to gather de eyes after de creature is dead, otherwise dey make de most horrible sound when ya try to take dem out.", completion = "Very good. Dese should be plenty!", objectives = "Gather 10 Razorwing Eyes and return them to Kumali. Then observe as she tries to make the stone with them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50114] = { id = 50114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering Out Information", description = "I guess you noticed it requires a special anvil to make it. And I suppose you want to know where to find a Khaz'gorian Smithing Anvil?\n\nWell, I don't know where you can find one, not to mention I never said you'd be able to actually craft the dang thing.\n\nNow if you wouldn't mind, I have more of these recipes to sell.", progress = "That recipe really is worth what you paid for it, regardless of whether you can craft it or not.", completion = "Alright, alright, fine! I'll tell you what I know.", objectives = "Press Grix Barlow for more information about where to find a Khaz'gorian Smithing Anvil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50115] = { id = 50115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing the Scenery", description = "Or maybe de problem is dat we don't need regular reagents. Maybe we need something dat only comes from being transmuted.\n\nAnything's worth a shot at dis point. Here is a recipe my old partner left behind.\n\nHe used to go out to de Slough and change de shrubs into bubbles, ya see.\n\nWhy, you might ask? 'Cause he loved transmuting everything. Part of de reason we never saw eye to eye.\n\nAnyways, bring me back some of dose bubbles and we'll see if we can use dem to make dis stone.", progress = "I've seen him using dem in lots of his projects, so there has to be some alchemical qualities to dem.", completion = "Dese bubbles seem...odd. But den again so is Zukashi.", objectives = "Go to The Slough and transmute Barberry Shrubs into Shrubbery Bubbles and gather 6 of them.\n\nBring them back to Kumali and observe as she tries to use them to make the stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50116] = { id = 50116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Possible Solution", description = "None of dese things are working. I can't believe I'm saying dis, but I think you're gonna have to find Zukashi.\n\nMaybe you could convince him to give up de other half of de recipe. He's pretty full of himself, but he isn't unreasonable.\n\nLast time I heard, he's staying in Nazmir near Gloom Hollow. Maybe it's best to tell him dis isn't about me.", completion = "Who are you? Another one of Kumali's apprentices coming to learn de true art of alchemy?\n\nOr is dere someting else you're interested in?\n\n<You explain to Zukashi that you're researching a special transmutation stone and that he might be able to help you.>\n\nOh, dat thing, eh? Heh. Ya, dat's a fine thing to have.\n\nBut if you want de knowledge I have, you're gonna have to help me with someting first, little mixah.", objectives = "Travel to Nazmir and seek out Zukashi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50117] = { id = 50117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deathly Draught", description = "De first thing I'd like you to do for me is to gather some deathshroom.\n\nDon't worry if you're not skilled at herbalism, they're very easy to pick. Dey typically grow where death lingers in the air.\n\nI'd try to de Frogmarsh to de southeast. De trolls dere have been making sacrifices of de creature dat inhabit de area.", progress = "Have you finally acquired my mushrooms?\n\nIt's a simple task, even for someone like you.", completion = "Well done, little mixah! Dat's plenty for what I need.", objectives = "Collect 15 Deathshrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50118] = { id = 50118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stone's Throw", description = "Now dis ingredient you might have some fun getting, little mixah. I'm gonna give you dese stones. They're able to turn things into other things.\n\nDose blood trolls, de ones giving de rest of us a bad name? Dey drink de weirdest things and it taints their bodies.\n\nI need their blood to finish my work here, but without de taint. Dese stones will turn dem into weaker creatures. Although, sometimes de stones turn dem into other things...\n\nBe careful with dem.", progress = "Ya never know what you'll get with transmuting things until ya try. Ain't dat right?", completion = "How'd ya like dem stones? Pretty fun, ya?\n\nAnd dis is plenty of blood. Good job, little mixah.", objectives = "Use the Bag of Transmutation Stones on blood trolls and kill them. Collect 8 Vials of Altered Blood from them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50119] = { id = 50119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chemically Compounded", description = "Now dat I have everything I need, I can finish dis project. My latest transmuation will be my finest yet!\n\nBut dis is not de place to test it. It could draw too much attention.\n\nIf you want to see it for yourself, little mixah, meet me to de north. Dere is a cave dere dat should be a safe spot for testing dis out.", completion = "This bag must have belonged to Zukashi. As you rummage through it, you see a slip of paper that appears to be torn.\n\nYou grab the parchment and begin reading.", objectives = "Meet Zukashi at the cave he mentioned. And be ready for anything to happen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50120] = { id = 50120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recipe for Success", description = "Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for.\n\nAn odd signature completes the recipe, signed, \"Silas Darkmoon\".\n\nKumali should be very pleased to see this once again.", completion = "Ya did it, {name}! Dis is de other half of de recipe!\n\n\n\nHere. You take dis copy and don't lose it. I'll make another copy and keep it in a safe place.\n\nDis way, if one of us forgets it, we'll know how to get it back again, ya see? Also, you make a better partner dan Zukashi ever did. Pleasure working with ya, {name}.", objectives = "Bring the torn paper back to Kumali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50121] = { id = 50121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Casting the First Stone", description = "Would you mind helping me out with something, {name}?\n\n<Elric motions you over to him.>\n\nYou see, I have this recipe that, well, I only have half of currently. I've been trying to remember the other half but just can't seem to recall it.\n\nMy EX-partner tore the recipe and ran off with the other half over a disagreement we were having. But the stone it makes is invaluable.\n\nHow about you grab some vials and start mixing the ingredients on this list. Perhaps together we can figure this out.", progress = "I wouldn't dare ask for the other half back, not after what Quintin said to me. I'll get this mystery figured out, you'll see.", completion = "Let's give it a try, shall we?", objectives = "Craft a Potion of Durability and a Potion of Shifting States using the recipes given to you. You can find the ingredients you need in Elric's shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50122] = { id = 50122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ocular Extracts", description = "My next idea involves a creature whose eyes are useful for certain alchemical recipes. At least for potions they are.\n\nHopefully they're just what we need for this and there aren't any further... miscalculations. Although, I don't entirely recall seeing them on the recipe's ingredient list... but my memory isn't exactly as good as it used to be.\n\nOh, you caught me rambling. How about you get those eyes and I'll start making the preparations for them.", progress = "Oh, I do hope you gathered the eyes post mortem. Those creatures make the most awful sound if you try to extract them while they're still alive.", completion = "Very good. These should be plenty!", objectives = "Gather 10 Highlands Mauler Eyes and return them to Elric.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50123] = { id = 50123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recipe For the Ages", description = "Yo, {name}, over here! You've look like you've been hammering away for a while. I can smell the flux on ya!\n\n<Grix gives you a wide grin.>\n\nListen, I've got a recipe for the most amazing blacksmith hammer you've ever laid your eyes on. And I'd be willing to let it go for a bit of ore.\n\nRevlis ore to be exact. It's a little rare, but you can find plenty of it over in Gol Koval in Drustvar. The elementals there are practically made of it.\n\nBring me back a haul of it, and the recipe's yours!", progress = "This recipe is probably worth a thousand, no TEN thousand gold! Blacksmiths all over will be envious of you, you'll see.", completion = "Yea, yea! That's the stuff!\n\nHere's your recipe, have fun with it.", objectives = "Bring Grix Barlow back 30 pieces of Revlis Ore from Gol Koval in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50124] = { id = 50124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing the Scenery", description = "The stone this recipe becomes is a transmutation stone. What if the missing reagents to make it come from something that's gone through the transmutation process?\n\nI'm willing to try anything at this point. Here's an old recipe my ex-partner devised.\n\nHe used to go out to Stormsong Valley, just south of the Highland Flats and change the shrubs there into bubbles.\n\nBring back some of those bubbles and we'll see if they're what we've been missing.", progress = "I've seen him use those globes in some of his projects in the past, so there is clearly some alchemical properties to them.", completion = "These bubbles seem...odd. But then again so is Quintin.", objectives = "Go to Stormsong Valley and transmute Barberry Shrubs into Shrubbery Bubbles and gather 6 of them.\n\nBring them back to Elric and observe as he tries to use them to make the stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50125] = { id = 50125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Possible Solution", description = "Nothing appears to be working. I can't believe I'm proposing this but I actually think we need to contact Quintin.\n\nWell, you should, as I doubt he'll speak to me. Perhaps you could convince him to part with the other half of the recipe?\n\nLast time I heard, he was staying in Drustvar near Arom's Stand. There's a lot of alchemists in those parts, but he shouldn't be too hard to find.\n\nBest not to tell him I sent you. He may not be as forthcoming with the recipe.", completion = "Who do we have here? I don't suppose you're an old apprentice of my little brother, Elric, come to learn true alchemy, are you?\n\n<You explain to Quintin that you're researching a special transmutation stone and that he might be able to help you.>\n\nOh, interested in making one of those, are you? Well, just like transmutation there must be some equivalent exchange.\n\nYou're going to have to do some things for me first. You can have the pleasure of being MY apprentice.", objectives = "Travel to Drustvar and seek out Quintin Whalgrene.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50126] = { id = 50126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deathly Draught", description = "The first thing I'd like you to do for me is to gather some deathshroom.\n\nDon't worry if you're not skilled at herbalism, they're very easy to pick. They typically grow where death lingers in the air.\n\nI'd try to the Crimson Forest to the south. The creatures that have overrun it seem to be covered in deathly magics.", progress = "Have you finally acquired my mushrooms?\n\nIt's a simple task, even for someone like you.", completion = "Oh yes, that's plenty for what I need. Well done, apprentice.", objectives = "Collect 15 Deathshrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50127] = { id = 50127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stone's Throw", description = "You may enjoy getting this next reagent for me. I have some special stones that have transmutative qualities, especially on living things. It's not too unlike the one you're trying to make.\n\nThe witches that plague these lands are imbued with magic. As is their blood.\n\nI need their blood to finish my latest project, but in an altered form. These stones should turn them into weaker creatures. Although, sometimes the opposite occurs...\n\nI'd recommend handling them with care.", progress = "You never truly know what a transmutation will yield until you try it. Wouldn't you agree, apprentice?", completion = "How did you find the stones? Fun, aren't they?\n\nOh, and this is plenty of blood. Well done.", objectives = "Use the Bag of Transmutation Stones on witches and kill them. Collect 8 Vials of Altered Blood from them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50128] = { id = 50128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chemically Compounded", description = "That appears to be everything. This latest transmutation will be my finest yet. And your prize waits at its completion, apprentice.\n\nBut I don't believe this is an appropriate place to test it out. It may draw too much attention.\n\nThere's a cave not terribly far from here which would prove to be a more suitable setting for such a test.\n\nMeet me there when you're ready to witness why transmutation is the only branch of alchemy worth learning.", progress = "This seems to contain some of Quintin's things.", completion = "This bag must have belonged to Quintin. As you rummage through it, you see a slip of paper that appears to be torn.\n\nYou grab the parchment and begin reading.", objectives = "Meet Quintin at the cave he mentioned. And be ready for anything to happen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50129] = { id = 50129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recipe for Success", description = "Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for.\n\nAn odd signature completes the recipe, signed, \"Silas Darkmoon\".\n\nElric should be very pleased to see this once again.", completion = "You have it?! I'm impressed you were able to get it from Quintin.\n\n<Elric grabs your half of the recipe and fetches a fresh piece of parchment. He begins copying down the information and once finished, walks back to you with it in his hand.>\n\nHere, this copy is for you. I'll make another copy for myself and keep it safe this time.\n\nIf you don't mind me saying, you've made a much better partner than Quintin ever did. It was a pleasure working with you, {name}.", objectives = "Bring the torn paper back to Elric.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50130] = { id = 50130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Gesture", description = "Life in the marsh has not been easy, {name}. We want to live in harmony with those that call it home, but our enemies out here threaten our existence.\n\nWork with us. Help the people of Sporeggar thrive.", completion = "Thank you for helping the people of Sporeggar, {race}. You are always welcomed here.", objectives = "Reach Friendly with Sporeggar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50131] = { id = 50131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Outside Perspective", description = "Thank you for everything you have done for my people, but they are still scared of outsiders.\n\nFight the bog lords and rescue the spore sacs in the Spawning Glen. The future of my people is at stake!", completion = "Thank you, {name}! Thank you.", objectives = "Reach Neutral with Sporeggar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50133] = { id = 50133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weed Whacking" }
quests[50134] = { id = 50134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gadgets and Gizmos Aplenty", description = "The militia may have given up on us, but we haven't given up on me!\n\nI'm a bit of a tinker, and I find that my harvest golems are better than any hired help I've ever had. They just need regular maintenance to keep running.\n\nOf course the Briarback are now taking over my fields, and my farmhands have gone into disrepair.\n\nIf you head out into the fields, can you grab the inner mechanisms from any of them that you find? That will stop them from exploding as well as help me plan my revenge.", progress = "Do you have the parts yet?", completion = "Perfect! With these parts I can rebuild my entire workforce. Or make one of them REALLY powerful.", objectives = "Collect 10 Harvester Gizmos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50135] = { id = 50135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop Vining!", description = "You may have noticed that the fields are a little... unstable right now.\n\nThe Briarback have been busy, growing those large bramble vines and boring tunnels underneath the farm. The vines have always been an important part of their borders, and they're expanding!\n\nGo down into the lower area and see if you can find who or what is making those vines grow. There's no way that they're growing like that naturally. If we can stop the vines we can retake this area!", completion = "Mystics using magic to shape the vines? I don't know much about magic, but I'm glad you stopped them.", objectives = "Slay the three Vinemasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50136] = { id = 50136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farming Stimulator", description = "The plants have gone amok since you defeated their masters! Don't worry though, I've got a plan.\n\nI've been busy fixing up one of the farmhands that didn't go completely haywire. It should have enough juice for one more trip through the fields.\n\nWe've got some serious technology in these harvesters. Their tools should be more than enough to take care of some small plants and even a couple quilboar.\n\nWhat do you say? You up for some farming the Stormsong way? Hop on in and get to work!", progress = "Take out as many of them as you can!", completion = "Yeah, that'll show them! Those quilboar will think twice before invading my farm again!", objectives = "Use the Piloted Farmhand to slay 30 enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50138] = { id = 50138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Bloodfire Ravine", description = "It is time to strike out and end de blood troll threat once and for all!\n\nWe travel back to Bloodfire Ravine, and dis time it is de blood trolls who will be sent running.\n\nMount up, and together we will show dem we are a force to be reckoned with!", completion = "You fought well! \n\nDe blood trolls are on de run. We must keep de momentum!", objectives = "Take Bloodfire Ravine from the Blood Trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50139] = { id = 50139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Link", description = "<Though burned, portions of the note in the architect's hand remain legible.>\n\nThey are... everywhere... disguised...\n\nEncrypted... blueprints...\n\nCipher...\n\nPontus... watching me...\n\n<The cipher must be needed to read the ship blueprints. It seems Pontus is the likely holder.>", progress = "We need to get to the bottom of all this before Lord Stormsong goes on the offensive!", completion = "A cipher? Of course! But by the great sea, what's it covered in?!", objectives = "Obtain the Architect's Cipher from Tideguard Pontus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50149] = { id = 50149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Weather Eye", description = "It would be wise to get a lay of the land before we put together a plan of action. \n\nInquisitor Notley is an expert falconer, and a reliable scout. He utilizes an ancient relic to see through the eyes of his falcon, allowing him to survey great distances. \n\nUnfortunately, Notley was injured during the fighting. Nothing serious, but it's left him unable to concentrate enough to control his falcon.\n\nPerhaps you could help?", progress = "What news do you bring?", completion = "It is good to know that there are still some left to save in Corlain. \n\nWe should focus our attention on them until we can devise a plan to bypass that barrier.\n\nI'll make sure to get this whistle back to Notley. Thank you, {class}.", objectives = "Speak with Inquisitor Notley at Watchman's Rise to scout the areas surrounding Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50150] = { id = 50150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting the Mood", description = "De voodoo love incense and romantic meal are ready, {name}. Take dem and place dem at de feet of Maka'fon. \n\nQuickly, if you could. Dat smell is... overwhelmingly, horribly, disgusting. \n\nCould you move any faster? \n\nAway. \n\nFrom us.\n\nFor de sake of de brutosaurs, of course.", progress = "Best get dese stinking things over to Maka'fon soon, {name}. I guarantee it will get her in de mood.", completion = "I am an expert on love and all of my previous mates can attest to dat. I have misread de reason for Maka'fon's mood. \n\nDe razorwings ate her last clutch of eggs and she will make no more until she feels safe and avenged.", objectives = "Place and light the Voodoo Love Incense near Irritable Maka'fon and offer her the Romantic Brutosaur Meal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50151] = { id = 50151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steady Ballast", description = "The Armory presents us a ripe opportunity, {class}... one I suggest we take.\n\nIf this battle were to draw out, we have little means to repair our arms and armor. A blacksmith is invaluable to any war effort, and Ballaster is one of our best.\n\nThe Armory is but a short ride from here. I suggest you get to Ballaster before it's too late!", progress = "The blacksmith won't survive long with the coven hunting him down. \n\nI'd recommend leaving posthaste.", completion = "Our fortunes are turning up. \n\nHaving a blacksmith at the tower will ensure our Inquisitors stay equipped for battle.", objectives = "Find Angus Ballaster at the Corlain Armory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50152] = { id = 50152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging for Scraps", description = "Well met, {class}.\n\nI hope you don't mind that I took the liberty to scout ahead and assess the situation at the armory.\n\nThe good news is that there still seems to be some salvageable arms left in the armory. The bad news, of course, is that the coven is after them as well.\n\nAdditional weapons could be a great boon to our cause. I recommend we take all we can carry.", progress = "What did you find at the armory?", completion = "So the coven didn't completely clean out the armory? This is good news for us.\n\nEven the most common villager in Drustvar can hold their own in a fight. With these arms we can turn each person we rescue to another soldier on the line.", objectives = "Collect 10 Quality Salvage from the Corlain Armory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50154] = { id = 50154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Say It's a Delicacy", description = "A romantic meal is de way to set up an evening for love. Dis is true for us, so why not for Maka'fon? Bring her something rare and pleasing to her palate. \n\nDiemetrodons near de water eat hard seed pods and partially digest them. With a little voodoo, something magical can happen to de pods. It may be disgusting to you and I, but de brutosaurs consider it a rare delicacy. Such is life. \n\nDere are plenty of diemetradons, so some must die dat de brutosaurs might live. Such is de purpose of death.", progress = "De pods we need become edible only in de belly of de diemetradons. Watch your fingers in dere... de scales are sharp.", completion = "De pods may be unpleasant to us, but de brutosaurs like dem just fine.", objectives = "Obtain 25 Partially Digested Pods from the bellies of nearby diemetradons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50157] = { id = 50157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Gold in Them There Fields", description = "We've still got some folks missing, and I could use your help finding them.\n\nWhile Brennadam is now secure, I worry for some of our farms closer to the quilboar kraul. We relied on the militia in the past to keep the quilboar back, but now that they've retreated to the east I worry that our outlying farms are in danger.\n\nGoldfield's farm is almost directly south of us, up the hill by the falls. While it's not surprising that he hasn't left, I would feel better if you checked in.", completion = "Roz always worries about me. I keep tellin' her I'm fine up here, but she never listens...", objectives = "Find Farmer Goldfield at his farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50158] = { id = 50158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Checking Out the Collapse", description = "If you've got a minute, there's a farmer out there who hasn't made it back yet.\n\nName's Burton and he's out by a farm right next to Briarback Kraul. If the quilboar were to strike out, his farm is one of the first in their way.\n\nI haven't heard anything from Burton. He mostly relied on his mechanical farmers to help him, so we don't know the situation out there.\n\nHead to the west and keep an eye out for him, would you?", completion = "I stayed behind to see if I could help... Everyone else made it back okay, right?", objectives = "Find Farmer Burton at his farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50161] = { id = 50161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovering Raimond", description = "The map we found earlier had some red markings, near the flower field. \n\nDo you think you could go up there and look for dad?\n\nI'm going to stay here and check out the rest of this stuff. \n\nI'd go with you... but, I'm sort of allergic to bees.\n\nOh, and take his boot. Just in case!", progress = "It is about time someone came looking for me!", completion = "Ahh, hah! Ancel sent you to find me, huh?\n\nHey, you found my boots too!? Marvelous!", objectives = "Find Raimond Mildenhall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50162] = { id = 50162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sticky Situation", description = "The scientific breakthroughs I've made, marvelous, absolutely marvelous... I'm so close to perfecting the formula!\n\nThe way the honey grows and crystallizes, simply beautiful. Well, as you can see, that's also part of my current predicament.\n\nPerhaps you can lend me a hand? Just fetch some royal jelly from the hives outside.\n\nOh, don't worry about the bees, they are sweet, gentle things. \n\nThey don't sting... much.", progress = "You get all the jelly yet?", completion = "Hope you didn't have any problems with bees. No, of course not... why would you? \n\nThey're totally harmless.", objectives = "Collect 60 Royal Jelly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50164] = { id = 50164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polly Want A Cracker?" }
quests[50165] = { id = 50165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bee Team", description = "We need to put things in order, and the next item on the list is these blasted wendigos terrorizing the farm. \n\nIf we can cull their numbers, it should be enough to drive them off!\n\nI've synthesized a superb solution that might be just what we need to solvent this sticky situation!\n\nToss these bottles at your foes and our friendly little apoideas should come to help.\n\nWhatever you do, please don't spill any on yourself...", completion = "Hah! Did you see the look of sheer terror on their faces when they saw the bee swarms? \n\nMarvelous!", objectives = "Kill 12 Highland Maulers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50168] = { id = 50168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Royal Succession", description = "I know, I know, okay... the farm is overrun by living honey and the bees have grown to massive proportions.\n\nI'll admit, things didn't quite go according to plan, but, extraordinary advancements in science do not come without some risk!\n\nI've been up here attempting to reduce aggression in the hive, an unfortunate side effect of my miscalculation, but I need another favor...\n\nYou're going to have to kill the Hive Mother and retrieve her stinger for me.", progress = "Oooh, ooh, do you have it!?", completion = "I'm glad you still have both of your eyes!", objectives = "Retrieve the Hive Mother's Stinger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50172] = { id = 50172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Crimsonwood", description = "Master Ashton has been taken into the forest. He isn't the only one. Mayor Royston's headcount came up short.\n\nIt seems our next steps are clear. We must go into the woods and save Master Ashton.\n\nMarten and I will sneak into the forest and meet you near some ruins further in.", completion = "The woods are crawling with witches. We'll have a fight on our hands if we're to save Master Ashton.", objectives = "Meet Inquisitor Cleardawn in the Crimson Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50173] = { id = 50173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Metals", description = "{class}, I have another objective we should consider. \n\nThe Bleak Hills Mine is not too far from our location. Though the miners there principally extract iron, they do on occasion find silver among the veins.\n\nWe do not know the current state of the mine, but it's unlikely that the coven has passed it over. However, it would be worth braving whatever dangers lie there to recover some silver to use against them.", progress = "Did you have any luck with the mine?", completion = "You found some silver? Excellent!\n\nThough it isn't much, any quantity of silver should help our efforts against the coven!", objectives = "Collect 10 Silver Nuggets from the Bleak Hills Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50174] = { id = 50174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Wrapped Up", description = "While I was able to get out of the mine, some of my friends weren't so lucky.  I saw those spiders wrap them up in their webs... probably to save them for a snack.\n\nIt was terrible, but all I could do was run.\n\nWill you help them?", completion = "You saved them!\n\nYou're certainly a hero in my book!", objectives = "Destroy Writhing Cocoons to rescue 8 Bleak Hills Miners in the Bleak Hills Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50175] = { id = 50175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Eight-Legged Curse", description = "Some terrible old hag unleashed a swarm of these horrible spiders in the mine!  I was barely able to make it out alive, but they've got me surrounded!\n\nYou can't leave me here! Please kill those things!", completion = "You... killed them!?\n\nOh thank you so much! It's been like a living nightmare in here!", objectives = "Kill 20 Bilefang spiders in the Bleak Hills Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50177] = { id = 50177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hold The Barricade!", description = "{name} they're rallying for a heavy assault!\n\nWe'll need to defend these barricades from attack! Are you with me?", progress = "That earned us some breathing room.", completion = "That witch! She must be the one guiding these attacks!", objectives = "Defend the barricades from attack!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50178] = { id = 50178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in the Rootway" }
quests[50181] = { id = 50181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[50187] = { id = 50187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[50195] = { id = 50195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilgemaul's Brigade", description = "<According to these orders, these assassins are being hired by a Sea Dog captain who is establishing a beachhead in Drustvar.\n\nTaking him out would deal a great blow to the Horde�s war effort, and might just put a halt to these ambushes.>", objectives = "Defeat Captain Bilgemaul in the Brackish Coast and loot his War Spoils.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50206] = { id = 50206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike Back" }
quests[50226] = { id = 50226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of Power", description = "Although the silithid disappeared for a time immediately following the destruction of Silithus, they have recently returned from beneath the ground.\n\nThese new silithid seem stronger than before!\n\nMy hypothesis is that the silithid are feeding on some kind of power source beneath the blade of Sargeras.\n\nI've been tasked with studying the effects that this mysterious power is having on the silithid hives.\n\nBring me as many intact silithid brains as you can carry and I'll begin the research!", progress = "Do you have the brains?", completion = "Oh! Look at these big, beautiful brains! I can't wait to dig in... thanks for your help, {name}! You can stay and watch if you want, but it may get a bit messy!", objectives = "Collect 10 Silithid Brains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50227] = { id = 50227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Larvae By The Dozen", description = "How did the silithid survive the blade of Sargeras? I'm perplexed!\n\nI've never encountered a species that can adapt to changes in the environment as quickly as the silithid can.\n\nThe larvae, or broodlings as they are often called, can evolve into a variety of silithid creature types based on the needs of the hive.\n\nIs it the hive mind that signals the evolutionary development of the larvae, or is some environmental factor at play?\n\nScience must find the answer!", progress = "Do you have the silithid larvae?", completion = "I see you have the broodlings! These will do nicely. Would you like to stay and watch me carefully dissect and catalog every detail of their anatomy?", objectives = "Collect 12 Silithid Broodlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50228] = { id = 50228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Survivor", description = "Silithus used to be overrun with members of the Twilight's Hammer.\n\nThe cult was presumed to be exterminated, but it has always survived in the shadows. Their numbers have dwindled, but the cult remains no less fanatical than at their peak.\n\nMost of the cultists here were destroyed by Sargeras in the attack, but a few still remain. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus.\n\nWe cannot let Michiel rally the remaining survivors to action. He must be stopped!", progress = "We cannot allow the Twilight's Hammer to regain their foothold in Silithus.", completion = "I see you have brought the head of Michiel Voidstrider. A gruesome task, but a necessary one. The Alliance thanks you for your service, {name}.", objectives = "Retrieve Michiel Voidstrider's head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50229] = { id = 50229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wee Bit O' Cloth", description = "{name}, is that you I hear rustlin' about out there? It's me, Angus Stormbrew!\n\nThere are cultists everywhere, so ye best keep yer voice down. Lean in close and cover yer nose while we talk!\n\nThis is the only outhouse in all o' Silithus! Trust me I spent hours lookin' all through the night. I decided to sneak in for a wee drop-off before the cultists woke up, but I've got a uhh problem...\n\nThere's no cloth to... you know...\n\nSee if ye can find me a wee bit o' cloth and sneak it in through the door!", progress = "Did ye acquire \"the goods?\"", completion = "Aye! This'll do nicely! Just give us a wee minute here...", objectives = "Collect 8 scraps of Twilight Silk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50230] = { id = 50230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of Power", description = "The silithid are all riled up and stronger than ever!\n\nMy guess is that they are feeding off of some kind of power beneath the ground. Probably near the blade of Sargeras!\n\nI've been ordered to study the effects that this mysterious power is having on the sillithid.\n\nBring me as many intact silithid brains as you can carry and I'll begin the research!", progress = "Hey kid! You got the stuff?", completion = "Holy moly! Look at the size of these big, beautiful brains! Where's my scalpel?! Wait... no... bring me the electric hacksaw. It's time for the big guns baby!", objectives = "Collect 10 Silithid Brains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50231] = { id = 50231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Larvae By The Dozen", description = "How did the silithid survive the blade of Sargeras?!\n\nI've never encountered a species that can adapt to changes in the environment as quickly as the silithid!\n\nThere's gotta be a way to tame these suckers! Harness their evolutionary biology for our profit!\n\nWe gotta start training 'em young! Forget about the old crusty adults, we need babies!\n\nSteal me as many of the silithid larvae as you can carry, and I'll find a way to train 'em!", progress = "Do you have the silithid larvae?", completion = "You've got the larvae! These are gonna make us a boatload o' money! I can already hear the gold jinglin' in my pockets!", objectives = "Collect 12 Silithid Broodlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50232] = { id = 50232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Survivor", description = "This land was once overrun with members of the Twilight's Hammer.\n\nThe cult was presumed to be exterminated, but darkness always survives in the shadows.\n\nMost of the cultists were destroyed by Sargeras in the attack, but a few yet live. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus.\n\nWe cannot let this fanatic rally the remaining survivors to action! Bring me his head!", progress = "We cannot allow the Twilight's Hammer to regain their foothold in Silithus!", completion = "I see you have brought the head of Michiel Voidstrider. It will look glorious mounted on a spike! The Horde thanks you for your service, {name}.", objectives = "Retrieve Michiel Voidstrider's head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50234] = { id = 50234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crews of Freehold" }
quests[50235] = { id = 50235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Safe Haven", description = "I brought Rastakhan to Zeb'ahari to hide him, {name}. I did not dream Zul's followers would find us so soon.\n\nDe people of Zeb'ahari are being hunted by those who answer to de prophet. I have brought dis upon dem by keeping de king in their village.\n\nHelp me save dem, {name}. Gather those who can still walk and send dem to me.\n\nI can do nothing for those who died, but we can still rescue de living.", progress = "I hope we can get dem out.", completion = "I will try to help dem secure their village.\n\nStay sharp, {name}. Zul will not stop while ol' Rastakhan's fate hangs in de balance.", objectives = "Rescue 12 Zeb'ahari villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50238] = { id = 50238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bramblethorn", description = "I was playing with Lord and Lady Sharptooth when Papa made me come with him. I dropped poor Lord Sharptooth and one of those big mean monsters grabbed him! \n\nPapa said he'd try to get him back but he's been gone a long time. I think he got busy. Mama and all the adults are busy doing stuff for Mayor Royston.\n\nLady Sharptooth and I are really sad. Can you beat up that mean monster and save my dino?", progress = "Did you find Lord Sharptooth? I think one of the really big monsters has him.", completion = "Yay! Oh. Y-you saw someone? My papa?\n\n<Lynn hugs her toy and sniffs>\n\nI haven't seen my Mama in awhile. I hope she's okay.", objectives = "Slay Bramblethorn and retrieve Lord Sharptooth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50239] = { id = 50239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Choice of Allies", description = "I was chosen to act as an ambassador to our new allies due to my experience with the pandaren joining the Alliance.\n\nI've made some notes about some potential allies that may be willing to join the Alliance.\n\nLearn more about them, then speak with me.", progress = "Hard choices must be made, {class}.", completion = "Your wisdom is always appreciated, {name}. The choice you make today will strengthen the Alliance.", objectives = "Learn more about potential allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50240] = { id = 50240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slip of the Tongue", description = "<As you approach, the blind Zandalari motions at you impatiently.>\n\nIt sounds like ya be headed somewhere in a hurry, little weed!\n\nSit down and share a tale with an old troll before ya head out on ya next adventa.\n\nI went on many adventas with my pterrordax when I was young. Explored dis whole valley!\n\nMy pterrordax died many years ago, but...\n\n<Blind Tra'wala smiles mischievously.>\n\nSometimes at night, I steal da guards' snacks to trick dese old pterrordaxes into lettin' me ride again. Ha!", objectives = "Steal a Pack of Pterrordax Snacks and use them to ride a pterrordax deeper into the city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50242] = { id = 50242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Choice of Allies", description = "As ambassador, it is my duty to bolster the Horde's ranks and strengthen our numbers in the face of danger.\n\nYour adventures have led you to many different people who can aid the Horde if we can convince them to join our cause.\n\nI've kept a record of the most promising potential allies. The choice of which to approach first is yours.", progress = "Is there a problem with my notes?", completion = "I have come to value your wisdom, {name}. The choice you make today will strengthen the Horde.", objectives = "Learn more about potential allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50247] = { id = 50247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mail Must Flow", description = "Due to all of the recent shenanigans, I'm running short on mailementals to sort letters.\n\nIt's a simple job, really - just toss the letter into the proper portal, where it will be whisked away to the far corners of Azeroth and beyond.\n\nI like to make a little game out of it. How many can you sort in one minute?", completion = "Well done! \n\nIs it not fulfilling? To see each letter safely to its destination?\n\nCome by and help any time!", objectives = "Help the Postmaster sort at least 15 letters within the time limit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50248] = { id = 50248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Second Ally For the Cause", description = "You have taken an important first step in strengthening the Alliance, {name}. Well done.\n\nBut I fear a single new ally will not deter the Horde. The warchief will not rest until Orgrimmar's forces vastly outnumber the defenders of Stormwind.\n\nI must ask that you work to secure our next ally. We cannot afford any delay.", objectives = "Choose a second ally to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50249] = { id = 50249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Boralus Triple Threat", description = "If Tallis honestly thinks that offing a few random soldiers is going to force us to give up Southwatch, he's in for a surprise. The reason why we haven't chased out the sorry troops in this camp is simply because we have more pressing plans.\n\nFernn has his lieutenants facing the Watch's cannons straight at Boralus as we speak. Those three are the real driving force of the attack.\n\n<The marine gives you a concerned look as he realizes what he said.>", progress = "What is it?", completion = "We finally got some useful information from him?", objectives = "Take out Fernn's three lieutenants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50250] = { id = 50250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Posthaste" }
quests[50251] = { id = 50251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spell Bound", description = "<The villager is held captive by a binding rune. Destroying the rune should free the villager.>", completion = "I shudder to think what they would have used those people for.", objectives = "Destroy 8 Binding Runes to free captive villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50252] = { id = 50252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mating Season Halftime", description = "Cala and I have both failed. Voodoo and science did not work. I am at a loss.\n\nI hope dat you can help us find a better path forward. De brutosaurs deserve a chance! \n\nPlease spend a little time with both of us. Perhaps you can find de way dat we cannot.", progress = "Please strategize with both Cala and myself to find a new plan to help de brutosaurs.", completion = "Thank you, {name}, for your help. Dis is de best of both worlds and de brutosaurs may benefit from it.", objectives = "Strategize with Cala Cruzpot and Witch Doctor Janagalar on how to use voodoo and science to get the endangered brutosaurs to mate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50253] = { id = 50253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Improvised Arsenal", description = "I don't know much about blacksmithing, but I'm pretty sure this won't be enough silver to outfit all of the Inquisitors.  We will need to find another way to use this.\n\nLet us hope that Ballaster can come up with something... creative.", progress = "What can ol' Angus do fer ye?", completion = "Ah, she's a beaut'! Back in the navy we used te stuff our muskets with scraps when we ran outta bullets. \n\nThis'll do the damage ye need, te be sure!", objectives = "Speak with Angus Ballaster to create a silver weapon at Watchman's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50254] = { id = 50254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Second Ally For the Cause", description = "One new ally will prove useful. A second will make us even stronger.\n\nEven now, the Alliance plots and schemes against us. We must move quickly, or they will strike before we are prepared to counter their aggression.\n\nSay the word when you are ready to begin pursuit of our next ally. There must be no hesitation.", objectives = "Choose a second ally to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50264] = { id = 50264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Farmhands", description = "We were running around trying to get the farm under control, but the bees, oh my goodness, the bees!\n\nThe giant monstrosities came out of nowhere and started dousing everyone in honey.\n\nI came up here to find Raimond, but before I knew it, I was covered too. \n\nThen, the strangest thing happened, the honey started growing around me!\n\nPlease, the other farmhands are still in trouble, you've got to help them!", completion = "Encased in honey, just waiting to be eaten. That must have been absolutely terrifying!", objectives = "Rescue the Honey Encased Farmhands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50265] = { id = 50265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Master Ashton", description = "I believe I see Master Ashton in a cage. He must be freed!\n\nThose witches with the long masks appear to be in charge. I bet they would have the means to open his cage.\n\nI will remain here to protect Apprentice Webb and keep the area secure.", completion = "We had a few visitors while you were gone but I took care of them. \n\nAshton's back and safe, though it appears he's seen some of the horrors here.", objectives = "Take a key from a Hexwood Binder and free Master Ashton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50266] = { id = 50266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittersweet", description = "Hey!\n\nI need to get out of here and get back to Falconhurst! My husband and I were looking for my daughter's favorite toy when I was taken. Please, I need to get out of here! I need to know my family is safe. \n\nThey took my gear. It's all around camp. Get me out of here then bring back my gear, please!", completion = "Thank you. I'll cut a path back to Falconhurst. They will pay for what happened to my family!", objectives = "Free Samantha Sweet then recover her gear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50268] = { id = 50268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give it a Little Juice", description = "Well, I admit that I feel a little better about this. If Witch Doctor Jangalar's voodoo can make Ben'jin react correctly, as the science says he should, then what do we have to lose? \n\nBless my formula or hex it or whatever they call it with Jangalar's voodoo cauldron.", progress = "Will voodoo make it smell funny? Nevermind, idle musings.", completion = "The consistency is the same... does it seem a little carbonated to you now? \n\nCan't wait to see if this works better than the original formula which, I feel like I need to say, SHOULD have worked fine.", objectives = "Put some voodoo on Cala's formula using Witchdoctor Jangalar's cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50270] = { id = 50270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep In the Core", description = "Look, you're gonna have to travel to some place called Deepholm and find an earthen down there.\n\nThe guy who sold the recipe to me said he got it from an earthen called...Ormhun! Ormhun something.\n\nI don't know too much about that place, but maybe you can ask the locals or something where he lives.\n\nNow if you don't mind, I have more recipes to sell.", completion = "Looking fer me, are ya? And what can old Ormhun be helping a fleshy out with?\n\n<You explain to Ormhun that you're trying to find a Khaz'gorian Smithing Anvil.>\n\nHa! Good luck with that! I haven't seen one of those in, oooh... centuries.\n\nLucky for you though, I know how ta make one. And I like the look of ya.\n\nI suppose I could come out of retirement and help ya for one last craft. It's been so long, it'll be nice to work the forge again. Just gotta find me hammer...", objectives = "Travel to Stormwind and take the portal to Deepholm. Seek out Ormhun Stonehammer when you arrive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50271] = { id = 50271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smash and Grab", description = "Most of the materials we'll need can be found right down here in the Deepholm.\n\nWe just need ta be discreet about it. If old Therazane catches wind of what we're up to, she might try ta put a stop ta it.\n\nBut let's not worry 'bout that. The first thing you'll need is diaminium. There are pillars that grow in the Alabaster Shelf rich with 'em.\n\nJust use yer old blacksmithin' hammer and smash those pillars ta bits. Don't worry about breaking the diaminium. We'll meld it all back tagether.", progress = "This'll be fun! I haven't made one of those anvils in ages!", completion = "Oh, did the drakes hear you smashing? Ha ha! Yea, I suppose that'd get their attention.\n\nStill though, this'll be plenty of diaminium.", objectives = "Go to the Alabaster Shelf and smash Diaminium Pillars. Collect 60 Diaminium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50272] = { id = 50272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ear to the Ground", description = "The next reagent ya need comes from the bellies of worms that burrow through this realm.\n\nWhile ya can find plenty o' worms all over, there's a certain type you'll need ta find. They're rarely seen above ground, but there are ways of coaxing 'em out.\n\nNamely making enough racket to piss 'em off! Ha ha! When ya see 'em rumblin' around beneath ya, use this thumper to draw 'em out.\n\nDeliver a killin' blow and get that metal from their wee bellies!", progress = "It's been a while since I went worm huntin'.\n\nWe used ta jump up and down ta rile them up before we made tha thumpers.", completion = "Now ya can't say ya didn't have fun throwin' those thumpers around, am I right?! Ha ha!\n\nGood haul you brought in, too. Should be plenty ta work with.", objectives = "Go to the Jagged Wastes and look for signs of worms. They usually kick up lots of dirt as they move around.\n\nDrop a thumper to make them surface, then kill them and collect 30 Endurite from them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50273] = { id = 50273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Locking Horns", description = "We've got tha metal for tha base and tha body, but there's one last part...\n\nTha horn of tha anvil was ta be made of ukrite. But that metal's been gone for ages.\n\nThere is another metal tha's very close ta it in terms of its durability. A type of gold tha trolls mined in abundance. And I know where ye can find it.\n\nTha trolls control an area called Atal'Dazar, a great city made o' tha stuff. If ye can find something horn-shaped in there, that'll save us tha trouble of shaping it from scratch.", objectives = "Go to Atal'Dazar and recover The Golden Horn of Rezan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50274] = { id = 50274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanic Forging", description = "Are ya ready, <lad/lass>?\n\nYou'll be doing the hammerin' while I take care of the last reagent we'll need.", completion = "Now you'll be able to craft some rather durable equipment. But best you be getting on yer way back.", objectives = "Meet Ormhun near the Shuddering Spires and help him craft a Khaz'gorian Anvil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50275] = { id = 50275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anvil's Away", description = "Take your anvil, and never speak of its methods of creation to anyone.\n\nShould I find out otherwise, you may find your next visit to my realm an unpleasant one.", completion = "Wait, what?! You actually got one? And you brought it back here?!\n\n<Grix's eyes widen as you drop the anvil down next to him.>\n\nDo you know what this means? It means I can start charging DOUBLE for the recipes!\n\nThank you, {name}. You're an amazing blacksmith!", objectives = "Bring the anvil back to Grix Barlow in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50276] = { id = 50276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recipe For the Ages", description = "Say, ya look like you been swingin' da hammah around quite a bit, <brudda/sista>. I can smell da flux on ya!\n\n<Zak'aal gives you a wide grin.>\n\nListen, I've got a recipe for da most amazin' blacksmit hammah ya ever be layin' ya eyes on. And I'd be willing ta let it go for a bit of ore.\n\nRevlis ore ta be exact. It be a little rare, but ya can find some of it over at Atal'Gral. Da naga dere use it ta make deir weapons.\n\nBring me back a haul of it, and da recipe be yours!", progress = "Dis recipe probably be wort a tousand, no TEN tousand gold! Blacksmits all over will be envious of ya, brudda.", completion = "Yea, yea! Dat's da stuff!\n\nHere be da recipe, have fun wit it.", objectives = "Bring Forgemaster Zak'aal 30 pieces of Revlis Ore from Atal'Gral in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50277] = { id = 50277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering Out Information", description = "Let me guess. You be lookin' at da recipe and noticed it require a Khaz'gorian Anvil ta make it. So now you be wantin' ta know where ta find a Khaz'gorian Smithing Anvil?\n\nLook, <brudda/sista>, I never said anyting about bein' able ta craft da hamma. Now if ya don't mind, I have more of dese recipes ta be sellin'.", progress = "Dat recipe really be wort what ya paid for it, no mindin' if ya be able ta craft it or not.", completion = "Easy, brudda. I'll tell ya what I know.", objectives = "Press Forgemaster Zak'aal for more information about where to find a Khaz'gorian Smithing Anvil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50278] = { id = 50278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep In the Core", description = "Look, ya gonna have ta travel ta Deepholm and convince dem ta be givin' up deir secrets. Dat's where da last anvil was made, or so I be hearin'.\n\nAnd I only be knowin' of one earten down dere who might be willin' ta work wit ya. His name be Ormhun Stonehamma'.\n\nHe be kind of an outcast, but not too hard ta find.", completion = "Looking fer me, are ya? And what can old Ormhun be helping a fleshy out with?\n\n<You explain to Ormhun that you're trying to find a Khaz'gorian Smithing Anvil.>\n\nHa! Good luck with that! I haven't seen one of those in, oooh... centuries.\n\nLucky for you though, I know how ta make one. And I like the look of ya.\n\nI suppose I could come out of retirement and help ya for one last craft. It's been so long, it'll be nice to work the forge again. Just gotta find me hammer...", objectives = "Travel to Orgrimmar and take the portal to Deepholm. Seek out Ormhun Stonehammer when you arrive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50279] = { id = 50279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anvil's Away", description = "Take your anvil, and never speak of its methods of creation to anyone.\n\nShould I find out otherwise, you may find your next visit to my realm an unpleasant one.", completion = "Wait, what?! Ya actually got one? And ya be bringin' it back here?!\n\n<Zak'aal's eyes widen as you drop the anvil down next to him.>\n\nDo ya know what dis means, brudda? It means I can be charging DOUBLE for da recipes!\n\nTank ya, {name}. You be an amazing blacksmit!", objectives = "Bring the anvil back to Forgemaster Zak'aal in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50287] = { id = 50287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unending Gorilla Warfare" }
quests[50288] = { id = 50288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therazane's Choice", description = "<You explain that you meant no disrespect to Therazane or to steal their secrets.>\n\nInteresting...\n\nI have a wonderful idea on how to solve this issue. Would you like to hear it?", progress = "To think a creature such as yourself would be freely given our secrets.\n\nI suppose I'll have to keep a closer eye on the goings on within my realm.", completion = "Your choice has been made. And an interesting one at that.", objectives = "Listen to Therazane's proposition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50295] = { id = 50295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Pulling Teeth", objectives = "Kill 25 wendigo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50296] = { id = 50296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Billy Goat Barber", objectives = "Use the Goat Shears on 6 Gentle Goats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50297] = { id = 50297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Head of Her Enemy", description = "You have done a wonderful thing, {name}. With de destruction of Gloomtail, Maka'fon is no longer bothered by de presence of de razorwings. It seems dat Gloomtail destroyed her eggs some time ago. \n\nTake Gloomtail's head to Maka'fon as proof dat he is gone. When she finds de scent of Ben'jin on it, she will once again seek a worthy mate. \n\nWhen Ben'jin senses dat, he will approach and nature will take over.", progress = "Take Gloomtail's head and offer it to Maka'fon. Let us see what happens next.", completion = "Dis is a wonderful moment and I feel hopeful dat dis species of brutosaur will survive and thrive here in de jungle.", objectives = "Place Gloomtail's head in front of Maka'fon so that she knows her territory is safe and that Ben'jin is the reason.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50299] = { id = 50299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gryphon Wranglin'" }
quests[50300] = { id = 50300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker's Call", objectives = "Meet Magni Bronzebeard at the Wound in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50303] = { id = 50303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", progress = "Not quite as beautiful as Suramar, is it?", completion = "So this is Orgrimmar. The orcs have made some... interesting aesthetic choices. Be careful of the spikes, {name}.\n\nAnd the smells. So many smells.", objectives = "Talk to Chromie in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50305] = { id = 50305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! \n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of the ren'dorei is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", progress = "So, how does Stormwind suit you?", completion = "Welcome to Stormwind. Though it is no Silvermoon, the city does have its charms.\n\nIf you came here expecting a warm welcome, I cannot say I have received one myself. But most folk are polite enough.\n\nNo matter. I am off to seek adventure! And perhaps a stiff drink.", objectives = "Talk to Chromie in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50306] = { id = 50306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odds and Ends", description = "Master Ashton's going to probably need something bracing once we get him free. I know of a quick potion guaranteed to get anyone to snap out of it, but I'm going to need a few things first.\n\nThose wicker dogs down there have some organic parts I can use and the witches are carrying bags of reagents. They'll almost certainly have what I need.\n\nBring those to me and I'll handle the rest once we get Master Ashton back.", progress = "Did you have any luck?", completion = "Hmm... Very interesting. And pungent. Perhaps my first order of business will be something to remove the smell.", objectives = "Collect 4 Organic Matter Samples and 3 Bags of Reagents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50313] = { id = 50313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like the devout sort. We have a lovely cathedral that will no doubt be of interest! \n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of the Lightforged is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", progress = "I can feel the Light in this place.", completion = "Welcome to this beautiful city, {name}. I am sure you will feel as welcome by the other members of the Alliance as I do.\n\nI have met a number of the city guards. Good people, though there are a few things they could learn from us.", objectives = "Find Chromie in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50315] = { id = 50315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not On the Itinerary" }
quests[50316] = { id = 50316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbance Detected: Ulduar", description = "You're late. Don't you remember the last time we had to deal with the tampering that allowed Yogg-Saron to escape from his prison underneath Ulduar? You were late then too. You should really try to be more punctual.\n\nWell, get going! Old gods! Keepers! Titan stuff! Get this one checked off your list so we can move on. We've got times and places to be.\n\n<Vormu gestures impatiently for you to leave.>", progress = "Exactly the same number of dwarves must be roasted as last time. Medium rare, of course - well done would be insanity.", completion = "Well this is worrisome. The Titan locks holding Yogg-Saron in place seem to have been artificially aged - these should have held for at least another forty millennia. The only ones with such power are dead.. aren't they? Or perhaps... no, that doesn't make any sense at all.", objectives = "Relive the expedition to Ulduar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50318] = { id = 50318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timely Summons from Northrend", description = "The blazing wanes in the shadow of a celestial mass, striking fear in to the seers. Seek out the sage Vormu in Dalaran, and lend her your aid.\n\nNo, not this Dalaran, the other one. Yes I know, it's terribly confusing.", completion = "We're behind schedule - let's get moving.", objectives = "Meet with Vormu in Dalaran above Crystalsong Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50319] = { id = 50319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", progress = "Not quite as beautiful as Highmountain, is it?", completion = "So many tauren! I think I've seen more tauren since I got here than in my entire life in Highmountain.\n\nThey all ask to touch my antlers. It's weird at first, but now I kind of like it.", objectives = "Talk to Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50321] = { id = 50321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mojo Mischief", description = "De soldiers you rescued spoke of de raids on Zandalar. Blood troll raiders, frothing at de mouth and possessing supernatural strength, overwhelmed de defenders. \n\nDey say dat their strength came from flasks of mojo dat de raiders drink before going into combat. We cannot allow de blood trolls to continue to possess them.\n\nGo down into de camp and destroy any of their flasks you may find.", objectives = "Destroy 6 Flasks of Viscous Mojo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50322] = { id = 50322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Feathery Fad" }
quests[50324] = { id = 50324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picturesque Fizzsprings Resort" }
quests[50325] = { id = 50325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping the Grand Rite", description = "The witches of the Crimsonwood are planning a Grand Rite, a powerful ritual. They intend to rip open reality and bring their dark master through!\n\nI suspect they may be in communion with Gorak Tul. We cannot allow their ritual to succeed.\n\nI need you to be the tip of the spear while I protect Master Ashton and Marten. Cause havoc and disrupt their rituals!", progress = "Destroy the Ritual Foci.", completion = "Damn!. We've slowed them down, but they are still working. To fully stop them we'll need to do more." }
quests[50326] = { id = 50326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ain't No Place Like Home", description = "Let me tell you, this is a big place, this Arathi Highlands, and I've no doubt at some point you are going to need to quick step it back to our lovely new base.\n\nHow about I help you out with that?", completion = "You know what you need? You need a good, easy way to get back to me to buy your things whenever you want. I can help ya there.", objectives = "Talk to Wistel Silversnitch", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50327] = { id = 50327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little 'Pick Me Up'", description = "Now to mix this up. \n\n<Marten begins to combine the components in a mug>\n\nI'm using some rather strong grog as a base, a drop of chilli extract and a handful of hearthbloom... There!\n\n<Marten hands you a mug>\n\nIt will taste worse than it smells, but it will bring Master Ashton to his senses. Please give this mug to him.", progress = "<Ashton stares into the distance, eyes wide, muttering under his breath.>", completion = "Oh! I say!\n\n<Ashton shudders and coughs>\n\nA bit less hearthbloom next time, Marten, but that did just the trick. Well done both of you.", objectives = "Give the mug to Master Ashton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50328] = { id = 50328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unconventional Aromatics", description = "A deal's a deal. You got the stingers for me, so here's that big batch of honey I promised.\n\nI hope you and Rhan'ka enjoy it... slowly. Seriously, do not eat this all at once.\n\nOh, and I'm always looking to trade. Swing by anytime you got something to sell or want to pick up some more honey!", completion = "Thank de loa dat de Sandfury didn't kill you and take dese.\n\nDe drinks are almost ready and dey really add the perfect flavor.", objectives = "Deliver the Batch of Bilewing \"Honey\" to Rhan'ka at the Goldtusk Inn.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50329] = { id = 50329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matrons of the Crimsonwood", description = "The witches in charge, the matrons...\n\n<Ashton shudders for a moment then composes himself.>\n\nThe matrons are the ones leading the Grand Rite. They are fearsome but not invulnerable. Removing some of them from the equation will bolster our chances of stopping this. \n\nTake this potion. It will be able to weaken the matrons so you might have a better chance of dispatching them.", progress = "Did you kill them?", completion = "The potion worked even better than anticipated! It is heartening to know my time spent in the witches'... care has yielded positive results.\n\nLosing some of their leadership will certainly set them back.", objectives = "Kill Matrons Elsbeth Garrick, Stefania Denholm, and Wilona Blackwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50331] = { id = 50331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Outcome", description = "There is no way to know when these orders were sent, or received.\n\nRokor took some Seekers north some time ago. They must be in that region by now. \n\nIf the temple still stands, warn Gral and his followers.\n\nIf it is lost, we must do what we can.", completion = "I fear those orders were found too late to help those that served here... about five years too late.", objectives = "Find Rokor near Atal'Gral, to the north.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50332] = { id = 50332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Hunter Mon", description = "In these valleys, the Mon be kepin' beasts alive only to serve as sport. For his entertainment.\n\nThe lives of others not be so cheap. Even the smallest creature can cause a whole lotta trouble. The Mon gonna be learnin' to respect that.\n\nI think this be a good time to teach this Big Hunter Mon a lesson, don't you? Be you my faithful messenger?", progress = "You taken my present to that big hunter mon yet, richmon?", completion = "Haha! Well done, richmon. It gonna take that Big Hunter Mon weeks to get de smell outta his ammo stores. Not to mention his feet. You have earned my favor.", objectives = "Survive Jani's prank on Nesingwary.\n\nIf you lose your saurid disguise, return to Jani for another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50335] = { id = 50335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grant Me Revenge", description = "I don't care who you pledge allegiance to, {race}. I need Hogger dead!\n\nHe--and the other cretins in this Light-forsaken place--have slain my men. The Alliance and the Horde may not see eyes-to-eye, but you must know that murdering my people in cold blood cannot stand.", progress = "Is it done? Is Hogger dead?", completion = "The uprising quelled, the elements calmed, and Hogger slain... I cannot thank you enough, {name}. My people have been avenged.\n\nThank you.", objectives = "Defeat Randolph Moloch, Lord Overheat, and Hogger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50336] = { id = 50336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable.\n\nLet's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg.\n\nOur leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work.\n\nProbably....", completion = "I'd love for you to come aboard as a full G-Team Commando, but our bylaws specifically prohibit Horde team members; however, I CAN enroll you in the G-Team Fan Club!\n\nHere's something for your trouble.", objectives = "Kill Mekgineer Thermaplugg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50337] = { id = 50337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "That Murd Doc is crazy, {class}. Never, ever, let you find yourself in an aircraft with that gnome.\n\nStealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000.\n\nThe Electrocutioner is in charge of the aircraft...\n\n...and I hate aircraft. I'm not getting in any sort of aircraft!\n\nUse this parachute to drop down afterwards and speak with Commando Face for your next job.", progress = "Woah! How did you see me!?", completion = "Took you long enough. Get behind the pillar before you blow our cover!", objectives = "Kill the Electrocutioner 6000.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50338] = { id = 50338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "How did you get in here, {name}?\n\nI'm Murd Doc of the G-Team and we could use the help of a {race} like you.\n\nHelp us defeat the irradiated inhabatants that now call Gnomeregan home, and I'll make you an honorary G-Team Commando!\n\nTake this parachute, jump down into the Hall of Gears, and take out the Viscous Fallout. After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.", completion = "The mission is far from over!", objectives = "Kill the Viscous Fallout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50340] = { id = 50340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steal Them Back", description = "<This empty crate of supplies is clearly marked with Kul Tiran signage. These must be the spoils of their raids on the farms of the valley.\n\nThe citizens would probably like their supplies back if there are any left.>", progress = "Keep an eye out for anything useful. This place is very dangerous.", completion = "It's not stealing if we're stealing them back. Hey! Are those my lucky anchors?", objectives = "Retrieve 5 Stolen Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50341] = { id = 50341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recent Discovery", description = "Earlier today, the leaders of the Horde gathered together for a feast in celebration of our victory over the Burning Legion.\n\nAs the others were feasting, Gallywix requested a private audience with the Dark Lady.\n\nIt seems that he has found a mysterious substance in Silithus... a magical ore unlike any we have ever encountered before. \n\nThe warchief has ordered me to fill you in on the details, in preparation for a special assignment.", completion = "The Dark Lady has given orders that you are to personally oversee the operation in Silithus.", objectives = "Speak with Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50343] = { id = 50343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mayhem at Mildenhall Meadery", description = "Ahhhh! <Sir/Miss>, please, I need some help!\n\nMy dad hasn't come back from the meadery and, and... well, when I went to look, there were giant globs of honey everywhere. \n\nBut... but, somehow, they were moving on their own. I even saw one eat a bunny, I swear!\n\nI'm scared to go back by myself, but I think dad is in trouble.\n\nCan you go with me?", completion = "Where did all of these things come from?", objectives = "Investigate the Mildenhall Meadery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50349] = { id = 50349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Overrun Mine", description = "It was horrible! I was in the mine nearby, just picking away at a rock and it jumped up and bit me in the neck! Since when can rocks walk around and bite people?\n\nI hightailed it outta there, but some crazy fools are sticking around trying to take the mine back. If you're eager to punch rocks you can find them down the road to the south.", completion = "Why aren't you wearing a miner's cap!? It's dangerous out here! Here, put this on.\n\nNow, I got a job for you. Real easy.", objectives = "Find Chief Miner Theock at Winterdeep Mining Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50350] = { id = 50350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need a Chemist", description = "All this chaos started when we were picking at a large Azerite node deep in the mine. The mine began to rumble and all of these blasted creatures burst from the ground. If we could just get rid of that vein, I am sure we could retake the mine.\n\nFirst, we need a chemist. The best one we got is in his lab across the river. Find him and he'll give you more instructions.", sourceObjective = "Find Head Chemist Walters.", sourceObjectiveStatus = "unverified-source-field" }
quests[50351] = { id = 50351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miner Operation", description = "The mine is in real trouble. We've been excavating for a short while, but never seen anything like this. Azerite doesn't just get up and walk around.\n\nIf we are going to take the mine back, we're going to need more help. We'll need an engineer and an explosives expert. I have two in mind, sisters actually, but they are caught behind the river in all the chaos.\n\nLocate the sisters and they'll help you with the next phase of the plan.", completion = "Good. We're all here.", objectives = "Locate Civil Technician Alena and Ordnance Handler Prim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50352] = { id = 50352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinch of Azerite", description = "I don't have time for idle chit chat! If you haven't noticed, rocks are running around doing who knows what?!\n\nHow about you help out and retrieve my chemistry kit. While you're out, smash some of those creatures and collect their dust. Prim will need both of those for the next step of the plan.\n\nMaybe we can figure out what has animated the Azerite.", progress = "Did you bring the dust?", completion = "Great job! We are going to put this to good use.", objectives = "Collect 45 Azerite Dust and Walters' Chemistry Kit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50353] = { id = 50353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boaring Company", description = "I don't see her body anywhere. That means she could still be alive.\n\nThe Briarback have been taking prisoners, and anyone who has ever been taken by them was never seen again.\n\nWe have a single chance here and we need to take it!\n\nCome with me into the kraul and free as many of the survivors as you can. And if you can, find Farmer Deal. See if she's still alive.", completion = "I was sure they were done for. You have my thanks.", objectives = "Find and rescue 7 Captured Farmers and Farmer Deal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50354] = { id = 50354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Look Out!", description = "Some of these quilboar are clearly lookouts. Those horns make it obvious, almost like I could see their task floating above their heads.\n\nI was able to kill one, but not before he blew that horn of his and summoned backup. I suggest you keep them silent before they do the same with you.\n\nIf we're going to get anywhere in there, you'll need to do it quietly. Here, Hobbs gave me a few of his sleeping darts. That should keep them quiet.", completion = "I'm amazed I made it here. This place is so heavily guarded...", objectives = "Kill 6 Briarback Lookouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50356] = { id = 50356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Meet Dynamite", description = "Thanks for your help out there, but we have to ask another favor from you.\n\nThese elementals must be coming from somewhere in the mine and we need you to locate that source. \n\nYou seem more than capable of handling yourself in there, but just for extra security I am going to send you with some of Prim's special dynamite. It has an extra kick from the Azerite dust that you gathered.\n\nGet in. Find the source. Put a stop to these elementals.", completion = "A trogg? Hmmm... He may have eaten quite a bit of Azerite to be able to cause all this.\n\nWith him gone, now we can clear out the remaining creatures here and get back to digging! Thank you for your help.", objectives = "Eliminate the source of the Azerite creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50358] = { id = 50358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Research", description = "The dark blade of Sargeras has cast a shadow of destruction over this land.\n\nIt seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning.\n\nIf it were up to me, I'd burn those wretched hives once and for all! However, it is not up to me.\n\nThe Dark Lady wants the surviving silithid dissected and studied. \n\nPixni Rustbomb is conducting the research and is in need of a \"collector.\"", completion = "You're here to collect the samples? It's about time they sent someone to help me out!", objectives = "Speak with Pixni Rustbomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50359] = { id = 50359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleanup Duty", description = "Wh...why, why is all of the honey alive and what happened to everybody?\n\nYou don't think... oh no! Please, {name}, tell me they haven't been eaten!\n\nAhhhh! That would be terrible. Please don't let me be eaten too!", completion = "Thanks for getting rid of those things, {name}.", objectives = "Kill 4 Flowing Honey and 4 Bubbling Mead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50360] = { id = 50360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar's Request", description = "Archmage Khadgar arrived while you were away. It seems that he is here to speak with you, {name}.\n\nHurry and see what it is that he wants. I want him gone as soon as possible.\n\nThe last thing we need is a human nosing around in Horde business!", completion = "It's good to see you, {name}. I suspect that my welcome among the Horde is wearing thin...", objectives = "Speak with Archmage Khadgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50363] = { id = 50363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Pigs", description = "They look cute enough now, but that's a new herd of battleboars in training.\n\nFarmers don't like waste, and it would be a shame to get rid of such useful creatures.\n\nEither way, we could use those pigs, and I'd rather have them with us rather than face a bloodthirsty one in a few years. You should find them up on top of the cliffs overlooking the center of the kraul. Go round up as many piglets as you can take with you and we'll make good use of them.", completion = "I will take these and make sure they get to the farms for proper training.", objectives = "Collect 8 Grazing Battle-Piglets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50364] = { id = 50364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood of Azeroth", description = "Do the leaders of the Alliance and Horde even know what they're fightin' over?\n\nThis substance that is risin' up from the wound is the lifeblood of Azeroth!\n\nWe need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die!\n\nI trust ye, {name}, and I know that yer voice carries great weight among the Horde. Ye must reason with 'em ta stop this madness!\n\n'Tis the only hope our world has...", completion = "The blood of Azeroth? Hmph.\n\nI'll make sure this news reaches the warchief, but this operation must continue until I'm ordered to cease!", objectives = "Deliver Magni Bronzebeard's message.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50365] = { id = 50365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Run For the Hills", description = "The quilboar are up to something, something big. You need to stop it!\n\nThey've been busy bringing supplies up to the caves above their sanctum. Preserved thorns, cauldrons of venom, giant totems...\n\nThey're preparing for war.\n\nGet up there and destroy those stockpiles before they can be used against the citizens of the valley!", completion = "Those supplies you destroyed should set them back. They must have been saving them for a while...", objectives = "Destroy the stockpiles of supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50367] = { id = 50367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anger in a Bottle", description = "<The bottle the quilboar was carrying contains a foul-smelling, orange liquid. You're not sure if it's safe to drink, but it can't hurt to gather some samples to bring back to the citizens of Brennadam.\n\nMaybe their alchemist can come up with an antidote to counter its effects.>", progress = "Do you have something for me?", completion = "This stuff smells awful. Maybe Hobbs will know what to do with it. Once we get out of here I'll make sure these samples get to him.", objectives = "Collect 10 Foul-Smelling Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50368] = { id = 50368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terror of the Kraul", description = "By all the gods of the sea, what a monster!\n\nI can barely believe what I am seeing, {name}. This ettin has undergone the same ritual that the brutes do, and it seems even angrier! If he gets out of here, we won't stand a chance.\n\nI know I ask the impossible, but I must: kill this monstrosity and save the whole valley from its wrath! Here, take one of the potion samples you brought me. It's probably dangerous, but you might need it to defeat this beast.", progress = "We have to kill that thing!", completion = "It's done! I was afraid you were done for, but you've saved us all!", objectives = "Defeat Bramblefist the Maddened.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50369] = { id = 50369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruin Potions" }
quests[50370] = { id = 50370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeper into the Woods", description = "We need to go deeper into the forest. The witches are clearly up to something even worse than I'd imagined.\n\nAs much as I have a duty to return to Lady Lucille with Master Ashton, I also have a duty to find out more about this threat to our people, and stop it if I can.\n\nGoing further into the forest is not without risk, but I believe it is one worth taking.", progress = "The risk has paid off", completion = "By my ancestors' anchors that is a large army! At least it doesn't appear to be mobile yet. And the tree... Clearly it is the focus of their efforts.", objectives = "Travel with Cleardawn, Ashton, and Webb deeper into the forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50371] = { id = 50371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons to Stormwind", description = "King Wrynn has requested that you return to Stormwind as soon as possible. There is an urgent matter that requires your attention.\n\nI will fill you in on the details as soon as you arrive.\n\nYou will find me at Lion's Rest. Be swift... our window of opportunity may already be closing!", completion = "At last you have arrived, {name}. The very future of the Alliance may depend on what I am about to tell you...", objectives = "Meet with Mathias Shaw in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50372] = { id = 50372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Research", description = "The dark blade of Sargeras has cast a shadow of destruction over this land.\n\nIt seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning.\n\nWe need to find out how the silithid avoided destruction and what effect the blade is having on their hives.\n\nThe crown wants the surviving silithid dissected and studied. \n\nTammy Tinkspinner is conducting the research and is in need of a \"collector.\"", completion = "You're here to collect the samples? Let's get started!", objectives = "Speak with Tammy Tinkspinner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50373] = { id = 50373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recent Arrival", description = "The situation in Silithus appears to be gaining more attention.\n\nArchmage Khadgar just arrived while you were away. It seems that he is here to speak with you, {name}.\n\nIt appears urgent. I would speak with him as soon as possible.", completion = "It's good to see you, {name}. I wish that I were here under more pleasant circumstances...", objectives = "Speak with Archmage Khadgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50374] = { id = 50374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood of Azeroth", description = "Do the leaders of the Alliance and Horde even know what they're fightin' over?\n\nThis substance that is risin' up from the wound is the lifeblood of Azeroth!\n\nWe need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die!\n\nI trust ye, {name}, and I know that yer voice carries great weight among the Alliance. Ye must reason with 'em ta stop this madness!\n\n'Tis the only hope our world has...", completion = "The blood of Azeroth? I'll make sure this news reaches Stormwind, but I must continue the operation until I am ordered otherwise.", objectives = "Deliver Magni Bronzebeard's message.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50375] = { id = 50375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride With Me", objectives = "Ride Gonk as he investigates the source of corruption nearby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50376] = { id = 50376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadliest Cache: Reel Big Fish", description = "Can ye believe the nerve of these scallywags? Questioning the very Coxswain of this here wharf?\n\nBah!\n\nLend me your ear for a moment or three. I've got a tale that'll put brew in your mug and a quiver in your boots!\n\nIt was the biggest, deadliest cache I ever did loot on these seas...", progress = "Want to hear more?", completion = "Don't listen to either of 'em. True every word, I tell ya!", objectives = "Listen to Coxswain Hook's tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50381] = { id = 50381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Hat Robbery", description = "Along this road the merchants ride. Taking dere wares from one place to another and lining them own pockets. \n\nOne Big Mon named Tik'su be the worst of all. He charge arms and legs outright and it even take trolls some time to regrow them parts.\n\nHis biggest pride? His hat. \n\nGo be my messenger, Rich-mon. Scare his burdened beast and knock off Tik'su. Then bring me his hat.", progress = "You had a chat with Tik'su about his hat yet, richmon?", completion = "Haha! Well done, richmon. You bruised Tik'su's pride and his backside. He gonna be hurtin' for a while. You have earned my favor.", objectives = "Successfully steal Tik'su's Hat.\n\nIf you lose your saurid disguise, return to Jani for another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50385] = { id = 50385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Indefatigable Purpose", description = "Its grip weakens, if only briefly. We must claim this place anew!\n\nFlopping, nightmarish horrors have infested the caves amongst the cove. Take the sacred blessings. Venture forth into the dark and find their altars. \n\nPurge their blasphemous constructions from our lands!", completion = "A victory... perhaps a turning point.", objectives = "Cleanse 3 Drowned Altars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50386] = { id = 50386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flush Them Out", description = "They lurk in the shadows, in the salt-soaked caverns. The dark brine beneath the pure gleam of the surface.\n\nI have seen them. They plague my dreams, their whispers are maddening. They speak of their master, clawing at the barrier...\n\nSearch the cliffs for their warrens. Find what lurks within and obliterate them all.", progress = "Ignorance of our enemy will invariably lead to defeat.", completion = "The things are driven back, for a time.", objectives = "Investigate and defeat what lies within 4 structures in the Forgotten Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50387] = { id = 50387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinkets and Baubles", description = "Beneath the tides, these terrors do not see fit to stay within their warrens.\n\nThey have emerged in the night, stealing away to the villages and indulging in their avarice. They will use the provisions against us, to serve in their rituals. Rituals of summoning and communion with powers too terrible to comprehend. \n\nThe populace is no concern of mine anymore, but I would not see these briny thieves to have their way. Relieve them of their plunder, and let them learn a bitter lesson.", progress = "Where there is no peril, there can be no glory!", completion = "Paid for in blood.", objectives = "Recover 3 crates of Stolen Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50388] = { id = 50388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weight of My Ambition", description = "As with the other settlements, I too relied on the services of sailors and watercraft to deliver supplies. They proved very useful in their diligence, and their silence.\n\nPredictably, they drew the attention of enemies, including those below the waves. Their anchor was hexed, dragging them beneath the ocean before they could so much as cry out.\n\nI have seen them, hoisting ethereal sails and singing shanties of the damned. If these waters are to be safe again, they must be silenced again. For good.", completion = "Finally, a sailor's death.", objectives = "Defeat the Drowned Captain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50389] = { id = 50389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malign Inspiration", description = "A long time ago, there was a maiden.\n\nA precocious child fond of song, she made it her hobby to shadow my every move. Charming at first.\n\nWalking on the pier's edge, she became entangled within the ropes surrounding a leering idol. At that time a tremor ran through the waves, giving the small push needed to send them both beneath the surface.\n\nI can hear her song still. At first I thought it a passing fancy, music upon the waves. I realize now the voice comes with sinister purpose.\n\nShe must die.", completion = "She was made their queen, and their slave.", objectives = "Kill the Enchanting Siren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50391] = { id = 50391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadliest Cache: Gun Fishin'", description = "Hook's got a screw loose in her head, I tell ya. Sharks workin' together on somethin'... phooey!\n\nIt does remind me of one of my favorite tales, though. Have I ever told ya 'bout the time I caught THE single largest, deadliest, most tentacled beast in all o' Azeroth?!\n\nAye, I thought not. It's not a story I'd tell ya sober. It was a day unlike any other...", progress = "Aye, lad?", completion = "Ozumat ain't around on account of I shot the blasted beast in its slimy face! Swear on me beard every word is true!", objectives = "Listen to Master Gunner Line's tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50393] = { id = 50393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Child of Pa'ku", description = "<The pterrordax egg is warm and trembling. It will hatch soon.>\n\nPerhaps a certain pterrordax loa can help you.", completion = "An egg? It does not appear to be one of my brood.\n\nWhere did you find this?", objectives = "Take the Pterrordax Egg to Pa'ku at Pterror Rise.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50394] = { id = 50394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Problem Now", description = "Hm. This egg does not belong to one of my brood, and I have no broodlings that need another sibling.\n\n<Pa'ku might be smiling or snarling. She is showing an awful lot of teeth.>\n\nYou will care for this little one. And you had better hurry.\n\nIt will hatch very soon.\n\nOh, and a little advice. If you want the little one to like you, you had better be the first thing it sees upon hatching.", completion = "<The tiny Pterrordax stares adoringly at you.>\n\nSkreeeee.", objectives = "Place the Pterrordax Egg at the empty nest and wait for it to hatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50395] = { id = 50395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Skies", description = "<Kua'fon turns his head toward the cliff and chirps eagerly. He spreads his tiny wings and flaps vigorously.>\n\nIt is time to leave the nest.", progress = "What do you need, grounded one?", completion = "I regret to say that this is life in the skies, sometimes. Not all hatchlings live to adulthood.", objectives = "Watch your hatchling take its first leap into the great unknown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50396] = { id = 50396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pterrible Fate", description = "<Kua'fon peers longingly toward the horizon and gives a keening cry.\n\nYou can take the pterrordax from the sky, but not the sky from the pterrordax. It's time to do something.\n\nPerhaps Pa'ku could offer some advice.>", completion = "It is good that you came to me. I was considering throwing the thing off the roost again.\n\nPerhaps there is another way.", objectives = "Ask Pa'ku for help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50397] = { id = 50397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Aspirations", description = "<Kua'fon studies you intensely. One single golden eye is trained on you, unwavering.>\n\nSkree.\n\n<He then turns his maw toward the horizon and spreads his wings wide.>\n\nSkree!\n\n<Is it finally time?>", completion = "<Kua'fon wheezes.>", objectives = "Fly?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50401] = { id = 50401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear of Falling", description = "Some young find their wings sooner than others. At least yours had the sense to keep them open.\n\nI would not worry too much about its safety- little ones tend to bounce.\n\nAs for this failure... the young must keep trying, and they must learn not to fear falling. It is now your task to teach it.\n\n<The loa smiles at you, all teeth.>\n\nIf it is reluctant to learn, you might consider bribery.", progress = "<Kua'fon quivers in fear and chirps at you in distress.\n\nPerhaps a treat could soothe your hatchling?>", completion = "<The hatchling inspects your hands warily.>", objectives = "Find your hatchling and convince it to return to the nest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50402] = { id = 50402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SKREEEEE!", description = "<Kua'fon stares at you for a moment, then opens his maw and unleashes a continuous screech.\n\nYou need help.>", progress = "<The hatchling's gaze scours your person in search of anything edible. It may be best to keep your fingers out of reach.>\n\nSkree!? Skree!", completion = "<Kua'fon swallows the dino chow whole.>\n\nSkree.", objectives = "Find out what is distressing your hatchling and address it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50412] = { id = 50412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Nest", description = "<Kua'fon peers up at you trustingly.>\n\nNow would be a good time to take him back to the nest.", completion = "<The hatchling settles into the nest.>\n\nSkree.", objectives = "Return Kua'fon to his nest in Pterror Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50417] = { id = 50417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruin Has Come", description = "There is a terror beneath the waves. It seeks to destroy my family, my house, and my legacy.\n\nYou must come, claim your destiny and deliver us from the terrors of the deep!\n\nFind our estate to the east, among the isles. We lived opulently in the shadow of the great fortress. We believed the priests would deliver us from the darkness below. Now that darkness has bubbled to the surface, whispering madness in our dreams.\n\nHurry. The air turns the darkest I have seen in my cursed existence.", completion = "You have answered the letter. Now you are bound to this place.", objectives = "Find the author of the Mysterious Letter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50418] = { id = 50418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadliest Cache: Sink and Swim", description = "Mph mph!\n\nMph mph mph mph mph. Mph mph mph.\n\nMph.\n\nMph mph? Mph!", progress = "Mph?", completion = "Mph mph mph. Mph.", objectives = "\"Listen\" to \"Sinker's\" \"tale\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50420] = { id = 50420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift" }
quests[50421] = { id = 50421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparring on the Spar" }
quests[50432] = { id = 50432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanic Innovation", objectives = "Spectacular! Marvelous! At last, I understand fully, and the titans themselves speak to me! They have shown me how to use the essences to craft the finest armors the world has ever seen, though I think the results may be... somewhat unpredictable.\n\n<Vridiel beams with pride.>\n\nWell, what are you waiting for? Bring me as many Wakening Essence as you can find!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50433] = { id = 50433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanchuli Disbanded", description = "I would like to say we are doing well, but we are not.\n\nDe Zanchuli Council is broken. Raal and I are all dat remain who are still loyal to King Rastakhan. You best bring news to your Horde and tell dem what transpired here.\n\nRaal and I will rally what support we can and head for de Zocalo.\n\nAnd hero, thank you for saving my life and my loa.", completion = "Only two of their six most sacred advisors? I had hoped more would have revoked the dark path they are on.", objectives = "Speak with Baine Bloodhoof in Dazar'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50443] = { id = 50443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to the Roots" }
quests[50444] = { id = 50444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Loa Road", description = "This road not be traveled much anymore. Except by those that serve the blood Loa. They be fools.\n\nI be wantin' my fun from those fools. Go to the spot I be markin' for you and plant this cursed coin. The silly blood trolls be seein' it and give us a laugh when they try to pick it up.\n\nJust be makin' sure that no other creature see you. Or else it be a quick trip back to the arms of Jani.", progress = "You taken that cursed coin to the pranking-place yet, richmon?", completion = "Haha! Well done, richmon. It gonna take those idiots forever to be gettin' outta this mess. You have earned my favor.", objectives = "Survive Jani's prank on the Amaki trolls.\n\nIf you lose your saurid disguise, return to Jani for another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50445] = { id = 50445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Controlling the Situation", description = "I have been observing this macabre army of, wood, flesh, and bone and how the witches and servitors control the lesser creations with charms. I believe I can craft an even more powerful charm - one we can use.\n\nIn the hearts of the servitors are the very strongest charms. They are used to anchor the Ancient Drust into their physical forms. They are precisely what we need.\n\nGood luck. It is doubtful that they will part with them easily.", progress = "Were you able to collect enough charms?", completion = "Excellent. I should be able to do some... Interesting things with these.", objectives = "Collect 5 Control Charms from the Haunted Servitors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50446] = { id = 50446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Witchrending", description = "A blunderbuss? I'd have to say, I wasn't quite expecting that.\n\nNonetheless, now that we have a weapon, we have an advantage. I think it's time we take the fight directly to the coven.\n\nMarshal Reade informed me that several of their Matrons have been spotted throughout Corlain. Let's show them what happens to an enemy of House Waycrest.", completion = "Let us hope this sends a message to the coven.  As long as we have weapons to fight them, we will persevere.\n\nSpeaking of weapons, I believe our blacksmith has an idea on how to take down that barrier. You should have a word with him.", objectives = "Use Witchrend to defeat Matrons Ceridwen, Adeline, and Letitia in Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50447] = { id = 50447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remembering the Fallen", description = "<This villager died clutching a brooch with what looks like a family crest. It looks like several villagers didn't survive the coven's occupation of Corlain.\n\nIt might be possible to identify the fallen by the keepsakes they carried. The survivors would likely be grateful to learn the fate of their loved ones.>", progress = "What's this?", completion = "I don't know what to say. That you would risk your life to bring these items to me speaks greatly of your character, mainlander.\n\nI will make sure these keepsakes make it to the friends and families of the fallen, as well as news of their fate. On their behalf, I thank you for your compassion.", objectives = "Collect 8 Personal Keepsakes from fallen Corlain Villagers in Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50448] = { id = 50448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Corlain" }
quests[50449] = { id = 50449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reeking Refuge", description = "Oh good, maybe you can make sense of this.\n\nI was just carving through a swath of the coven's lackeys when I stumbled across this field. Something here has knocked these guys completely out of commission!\n\nI can't seem to find the source, but maybe you'll have better luck. I'm more used to hitting things than investigating them.", completion = "You don't look like you're in league with the coven, so what are you doin' in Corlain?", objectives = "Investigate what is disabling the coven's minions in Hocking's Plot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50450] = { id = 50450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Offensive Harvest", description = "So you're takin the fight to the coven with the Waycrest girl, eh?  Ya might just be able to take advantage of their apparent onion aversion.\n\nWhile you're out rootin' in the field, keep an eye out for any onions bulging out of the ground. Those ones should be particularly aromatic, and should cause some fits in the coven's minions if you keep it on ya.\n\nJust try not to take too much, right? I need enough left in the fields to keep the farm safe.", progress = "Did ya find any good ones?", completion = "That bunch should serve ya well.", objectives = "Collect 7 Aromatic Onions from Hocking's Plot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50451] = { id = 50451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eating Through the Defenses", description = "Not sure why and don't rightly care, but for some reason the coven can't come near my onion field. So long as my crop doesn't give out, I can hole up in here as long as it takes.\n\nUnfortunately, those boars got the same idea and now they're eatin' up my harvest! If they keep that up, soon there'll be nothin' keepin' the coven at bay!\n\nIf you can do me a favor and thin them out, I'd be happy to let you take some of these onions with you.", progress = "How's the boar situation?", completion = "That oughtta do it for a spell.\n\nThanks for the help, stranger.", objectives = "Kill 8 Scavenging Boars in Hocking's Plot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50452] = { id = 50452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potent Protection", description = "Here ya go, I got them onions bundled up nicely for ya.\n\nGive my regards to Miss Waycrest, will ya? Her allies are welcome on my farm anytime.", completion = "The coven is vulnerable to onions!?  I remember my nan used to tell stories about them warding off evil, but I never thought to take it literally!\n\nThis is quite the discovery!", objectives = "Deliver the Sack of Aromatic Onions to Lucille Waycrest at Watchman's Rise.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50453] = { id = 50453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrier Buster", description = "Oy, {name}! I think I might have a solution te that pesky barrier keepin ye out of Corlain proper! \n\nI took the silver we had left 'ere an' doctored up one o' these cannonballs. The walls surroundin' Corlain are festooned with defensive cannons. Get one pointed at the gate, ye can send this beauty right into the barrier!\n\nYe'll need a hefty pinch of powder te get this thing movin', though - it's a bit on the heavy side. Ye can likely find some in the camp outside the walls.", progress = "I don't think these guys will be needin' this cannon anymore.", completion = "Quite a bit of powder ya got there.\n\nCareful ya don't take the whole wall down.", objectives = "Collect 5 Blasting Powder from Pikeman's Ridge and bring them to Inquisitor Sterntide outside the gate into Upper Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50454] = { id = 50454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Traitor's Death", description = "It has come to my attention that you intend to assault the camp outside of the walls. If this is so, I have a request.\n\nThough most of the guardsmen who fight against us were turned to the coven against their will, Captain Goodspeed and his brigade of halberdiers gave their souls willingly to the Heartsbane. They are traitors and an affront to the Waycrest Guard.\n\nYou will find Goodspeed and his men stationed at the camp.  I would consider it a personal favor if you would cut them down to the last.", progress = "Is it done?", completion = "Captain Goodspeed was a stain on the reputation of the Waycrest Guard.\n\nI hope his end was painful.", objectives = "Kill Captain Goodspeed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50455] = { id = 50455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leaving the Nest", description = "It looks like the coven hasn't managed to enthrall all of our falcons. I can see some untainted ones still in cages in the training yard.\n\nOur falcons are well trained, and should know to fly to one of our other yards if something happens to their handlers. \n\nIf you can just release them from their cages, they should be able to make it to safety.", completion = "Nice work!  With any luck, the falcons should head back to roost at Arom's Stand.\n\nThough really, I'd prefer they be anywhere other than in the coven's clutches.\n\nYou have my thanks.", objectives = "Open 5 Falcon Cages in the Corlain Aviary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50456] = { id = 50456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexed Hatchlings", description = "I've found where those evil witches have been tainting our falcons! You see those charms? \n\n<Notley motions toward the high perches and roofs nearby.>\n\nThey're using those to infect our flock with their evil magic as they hatch.  I think Winston can get up there to take out the charms, but someone will need to direct him.\n\nI'm not quite healed up enough to take on a whole camp of falconers. Can you help?", progress = "Have you taken care of the charms?", completion = "The charms are broken? That's a relief!\n\nWe may just be able to save our flock after all.", objectives = "Use the Falconer's Whistle to destroy 7 bewitching charms in the Corlain Aviary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50457] = { id = 50457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break On Through", description = "Cannon's ready, boss.\n\nCare to do the honors?", completion = "Ballaster's plan worked! He is certainly a resourceful blacksmith.\n\nCome, Inquisitor. Waycrest Manor is just ahead!", objectives = "Use the Ramparts Cannon to break the barrier at the gate to Upper Corlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50459] = { id = 50459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vugthuth" }
quests[50461] = { id = 50461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zujothgul" }
quests[50466] = { id = 50466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's Gone Mad!", description = "Ol' Wildtusk has withstood years of attacks by young hunters that are overeager and underskilled.\n\nNone could take him.\n\nHis wounds have finally done him in. He just won't go down. Find that crazy riverbeast bull, and help him let go of his mortal shell.", completion = "Thank you for helping him on his way.\n\nDat Wildtusk, he has been watching dese hills for years long past. Some beast will have big shoes to fill!", objectives = "Kill Wildtusk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50468] = { id = 50468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shul-Nagruth" }
quests[50474] = { id = 50474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Other Side" }
quests[50476] = { id = 50476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Awaits", description = "{name},\n\nThere are important matters I would like to discuss with you, but discretion is of the utmost importance. \n\nMeet me in my chambers in the Undercity where I can assure our privacy has not been compromised. \n\nEnsure that you are not followed; Orgrimmar has become riddled with SI:7 spies. It would seem that that King Anduin and Mathias Shaw are desperate to know what our next move is. How admirable.", completion = "Glad you could make it so quickly, {name}.", objectives = "Report to Warchief Sylvanas Windrunner in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50481] = { id = 50481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Hall of the Drust King", description = "I've been watching a lot of activity going on at the ruins at the base of the massive tree by the lake. What Master Ashton reported is accurate - something important is going on down there. \n\nWe've disrupted their rituals but I worry we might have been too late.\n\nWe need to go over there. If there is anything remaining, we must destroy it.", progress = "We must confront Gorak Tul.", completion = "We've wounded him or he wouldn't have retreated as he did. Our victory won't last long unless we do something about his army.", objectives = "Confront Gorak Tul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[50483] = { id = 50483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underlord Xerxiz" }
